// BAPS Rajkot branding assets. Put both JPG files in the Vite public/ folder.
const APP_LOGO = "data:image/png;base64,";
const PROFILE_HERO = "data:image/jpeg;base64,";


function SafeImage({src, alt="", style, className}){
  const [failed,setFailed]=useState(false);
  if(failed) return <div aria-label={alt} className={className} style={{...style,display:"grid",placeItems:"center",background:"linear-gradient(135deg,#eaf2fa,#d9e5f1)",color:C.brand,fontWeight:700,fontSize:11,textAlign:"center",overflow:"hidden"}}>BAPS Rajkot</div>;
  return <img src={src} alt={alt} className={className} onError={()=>setFailed(true)} style={style}/>;
}

function useAppBranding() {
  useEffect(() => {
    document.title = "BAPS Rajkot";
    let icon = document.querySelector('link[data-baps-favicon="1"]');
    if (!icon) {
      icon = document.createElement("link");
      icon.rel = "icon";
      icon.dataset.bapsFavicon = "1";
      document.head.appendChild(icon);
    }
    icon.type = "image/jpeg";
    icon.href = APP_LOGO;
    let apple = document.querySelector('link[data-baps-apple-icon="1"]');
    if (!apple) {
      apple = document.createElement("link");
      apple.rel = "apple-touch-icon";
      apple.dataset.bapsAppleIcon = "1";
      document.head.appendChild(apple);
    }
    apple.href = APP_LOGO;
  }, []);
}

// Cover art: deterministic gradient + icon per project, standing in for a
// property photo the way the reference booking-app cards use a hero image.
const COVER_GRADIENTS = [
  "linear-gradient(135deg,#123F73 0%,#2C6AA8 60%,#6FA6D6 100%)",
  "linear-gradient(135deg,#0A2D52 0%,#123F73 55%,#3E7CB5 100%)",
  "linear-gradient(135deg,#1B4E86 0%,#3E7CB5 55%,#9FC6E8 100%)",
  "linear-gradient(135deg,#0E355F 0%,#1B4E86 55%,#5C93C7 100%)",
];
function hashStr(s){let h=0;for(let i=0;i<String(s||"").length;i++){h=(h*31+String(s).charCodeAt(i))|0}return Math.abs(h)}
function coverGradient(seed){return COVER_GRADIENTS[hashStr(seed)%COVER_GRADIENTS.length]}
function categoryIcon(category=""){
  const c=String(category||"").toLowerCase();
  if(c.includes("food")||c.includes("annakut"))return Sparkles;
  if(c.includes("event")||c.includes("festival")||c.includes("samaiyo"))return CalendarCheck;
  if(c.includes("seva")||c.includes("service"))return HeartHandshake;
  return FolderOpen;
}
function ProjectCover({project,height=132,radius=22,children}){
  const Icon=categoryIcon(project.category);
  return <div style={{position:"relative",height,borderRadius:radius,overflow:"hidden",background:coverGradient(project.id||project.name),flexShrink:0}}>
    {project.coverPhoto?<SafeImage src={project.coverPhoto} alt={`${project.name||"Project"} cover`} style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>:<div style={{position:"absolute",inset:0,display:"grid",placeItems:"center",opacity:.16}}><Icon size={Math.round(height*0.62)} color="#fff" strokeWidth={1.2}/></div>}
    <div style={{position:"absolute",inset:0,background:"linear-gradient(180deg,rgba(10,45,82,0) 35%,rgba(10,45,82,.48) 100%)"}}/>
    {children}
  </div>;
}

function useBrandFonts() {
  useEffect(() => {
    const id = "baps-radix-fonts";
    if (document.getElementById(id)) return;
    const link = document.createElement("link");
    link.id = id;
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Sora:wght@400;500;600;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

