    {tags.length>0&&<div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:8}}>{tags.map(t=><button key={t} type="button" onClick={()=>toggle(t)} style={{display:"inline-flex",alignItems:"center",gap:5,border:`1px solid ${C.brand}`,background:C.brand,color:"white",borderRadius:5,padding:"5px 8px",fontSize:10,fontWeight:700,cursor:"pointer",...sans}}><Tag size={11}/>{t}<X size={11}/></button>)}</div>}
