const VAPID_PUBLIC_KEY = import.meta.env.VITE_VAPID_PUBLIC_KEY || "";

function urlBase64ToUint8Array(base64String){
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const rawData = window.atob(base64);
  return Uint8Array.from([...rawData].map(char => char.charCodeAt(0)));
}

async function registerPushSubscription(memberId){
  if(!("serviceWorker" in navigator) || !("PushManager" in window)){
    throw new Error("આ app Web Push support કરતું નથી.");
  }
  if(!VAPID_PUBLIC_KEY){
    throw new Error("VITE_VAPID_PUBLIC_KEY configure કરેલ નથી.");
  }

  const registration = await navigator.serviceWorker.register("/sw.js");
  await navigator.serviceWorker.ready;

  const permission = await Notification.requestPermission();
  if(permission !== "granted"){
    throw new Error("App notification permission મળ્યું નથી.");
  }

  let subscription = await registration.pushManager.getSubscription();
  if(!subscription){
    subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
    });
  }

  const payload = {
    member_id: memberId,
    endpoint: subscription.endpoint,
    subscription: subscription.toJSON(),
    updated_at: new Date().toISOString(),
  };

  await sb("push_subscriptions?on_conflict=endpoint", {
    method: "POST",
    headers: {Prefer: "resolution=merge-duplicates,return=minimal"},
    body: JSON.stringify(payload),
  });

  return subscription;
}

function NotificationBell({currentUser,projects=[],onOpen,onClose,fullPage=false}){
  const[open,setOpen]=useState(false);const[items,setItems]=useState([]);const[loading,setLoading]=useState(false);
  const[permission,setPermission]=useState(()=>typeof Notification==="undefined"?"unsupported":Notification.permission);
  const projectIds=useMemo(()=>projects.map(p=>String(p.id)).filter(Boolean),[projects]);
  const isRelevant=useCallback((n)=>n.audience==="all"||(n.memberId&&n.memberId===currentUser.id)||(n.audience==="project"&&n.projectId&&projectIds.includes(String(n.projectId))),[currentUser.id,projectIds]);
  const load=useCallback(async()=>{
    if(!currentUser)return;setLoading(true);
    try{
      const r=await sb("notifications?select=*&order=created_at.desc&limit=100");
      const seenKey=`baps-notifications-read-${currentUser.id}`;let readIds=[];try{readIds=JSON.parse(localStorage.getItem(seenKey)||"[]")}catch{}
      setItems((r||[]).map(mapNotificationRow).filter(isRelevant).map(n=>({...n,read:readIds.includes(n.id)})).slice(0,50));
    }catch(e){console.warn("Notifications load error:",e)}finally{setLoading(false)}
  },[currentUser,isRelevant]);
  useEffect(()=>{load()},[load]);
  useEffect(()=>{if(!currentUser)return subscribeRealtime(`notifications-${currentUser.id}`,{"notifications":({eventType,record})=>{const n=mapNotificationRow(record);if(eventType==="DELETE"){setItems(prev=>prev.filter(x=>x.id!==n.id));return}if(!isRelevant(n))return;setItems(prev=>prev.some(x=>x.id===n.id)?prev:[{...n,read:false},...prev].slice(0,50));if(typeof Notification!=="undefined"&&Notification.permission==="granted"){try{new Notification(n.title,{body:n.message,tag:n.id})}catch{}}}})},[currentUser,isRelevant]);
  const unread=items.filter(x=>!x.read).length;
  const markRead=id=>{setItems(prev=>prev.map(x=>x.id===id?{...x,read:true}:x));try{const key=`baps-notifications-read-${currentUser.id}`;const old=JSON.parse(localStorage.getItem(key)||"[]");if(!old.includes(id))localStorage.setItem(key,JSON.stringify([...old,id].slice(-200)))}catch{}};
  const markAllRead=()=>{const ids=items.map(x=>x.id);setItems(prev=>prev.map(x=>({...x,read:true})));try{localStorage.setItem(`baps-notifications-read-${currentUser.id}`,JSON.stringify(ids.slice(-200)))}catch{}};
  const enablePush=async()=>{if(typeof Notification==="undefined"){appToast("App notifications are not supported here.","error");return}try{const p=await Notification.requestPermission();setPermission(p);if(p!=="granted"){appToast("Notification permission was not granted.","info");return}await registerPushSubscription(currentUser.id);appToast("Background notifications enabled.","success")}catch(e){console.error("Push setup error",e);appToast(`Could not enable background notifications. ${e?.message||"Unknown error"}`,"error")}};
  return <div style={{position:"relative"}}>{!fullPage&&<button onClick={()=>{if(onOpen){onOpen();setOpen(true)}else setOpen(v=>!v)}} aria-label="Notifications" style={{width:38,height:38,borderRadius:12,border:"1px solid #dbe3ec",background:"white",color:C.brand,display:"grid",placeItems:"center",position:"relative",cursor:"pointer",boxShadow:SHADOW.flat}}><Bell size={17}/>{unread>0&&<span style={{position:"absolute",right:-2,top:-2,minWidth:16,height:16,padding:"0 4px",borderRadius:99,background:C.brand,color:"white",fontSize:9,fontWeight:700,display:"grid",placeItems:"center"}}>{unread>99?"99+":unread}</span>}</button>}{(open||fullPage)&&<div style={fullPage?{position:"fixed",inset:0,background:"#f9fafb",overflow:"hidden",zIndex:200,display:"flex",flexDirection:"column"}:{position:"absolute",right:0,top:44,width:340,maxWidth:"calc(100vw - 28px)",background:"white",border:"1px solid #e5e7eb",borderRadius:16,boxShadow:"0 16px 45px rgba(0,0,0,.12)",overflow:"hidden",zIndex:100}}><div style={{padding:fullPage?"16px 20px":12,borderBottom:"1px solid #eef1f5",display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,background:"white"}}>{fullPage?<button type="button" onClick={()=>{setOpen(false);onClose&&onClose()}} style={{border:0,background:"transparent",color:C.brand,display:"flex",alignItems:"center",gap:5,fontSize:11,fontWeight:700,cursor:"pointer"}}><ChevronLeft size={16}/>Back</button>:<span/>}<b style={{fontSize:fullPage?18:12,color:C.brand}}>Notifications</b><button onClick={markAllRead} style={{border:0,background:"transparent",fontSize:10,color:C.brand,cursor:"pointer"}}><CheckCheck size={13}/> Mark all read</button></div><div style={fullPage?{flex:1,overflowY:"auto",padding:"0 20px 20px"}:{maxHeight:420,overflowY:"auto"}}>{loading?<div style={{padding:20,textAlign:"center"}}><Loader2 className="animate-spin" size={16}/></div>:items.length?items.map(n=><button key={n.id} onClick={()=>markRead(n.id)} style={{display:"block",width:"100%",textAlign:"left",border:0,borderBottom:"1px solid #f3f4f6",background:n.read?"white":"#f5f9fd",padding:12,cursor:"pointer"}}><div style={{display:"flex",gap:8}}><div style={{width:8,height:8,borderRadius:99,background:n.read?"#d1d5db":C.brand,marginTop:5,flexShrink:0}}/><div><div style={{fontSize:11,fontWeight:700,color:"#111827"}}>{n.title}</div><div style={{fontSize:10,color:"#5f6876",marginTop:3,lineHeight:1.45}}>{n.message}</div><div style={{fontSize:8,color:"#9aa3af",marginTop:5}}>{n.audience==="project"?"Project notification":"All haribhakto"} · {new Date(n.createdAt).toLocaleString()}</div></div></div></button>):<div style={{padding:24,textAlign:"center",fontSize:11,color:"#9aa3af"}}>No notifications</div>}</div>{permission!=="granted"&&<div style={{padding:fullPage?"14px 20px":10,borderTop:"1px solid #eef1f5",background:"white"}}><button onClick={enablePush} style={{width:"100%",border:"1px solid #dbe3ec",background:"white",borderRadius:9,padding:8,fontSize:10,color:C.brand,cursor:"pointer"}}>Enable app notifications</button></div>}</div>}</div>;
}

function NotificationComposer({onSend,projects}){
  const[title,setTitle]=useState("");
  const[message,setMessage]=useState("");
  const[audience,setAudience]=useState("all");
  const[projectId,setProjectId]=useState("");
  const[busy,setBusy]=useState(false);
  const send=async()=>{
    if(!title.trim()||!message.trim()){appToast("Title and message are required.","error");return}
    if(audience==="project"&&!projectId){appToast("Select a project.","error");return}
    setBusy(true);
    try{await onSend({title:title.trim(),message:message.trim(),audience,projectId:audience==="project"?projectId:null});setTitle("");setMessage("");setAudience("all");setProjectId("")}
    finally{setBusy(false)}
  };
  return <div className="baps-card" style={{background:"#fff",padding:16}}>
    <div style={{display:"flex",alignItems:"center",gap:9,marginBottom:14}}>
      <div style={{width:34,height:34,borderRadius:11,background:"var(--ui-blue-soft)",color:C.brand,display:"grid",placeItems:"center"}}><Megaphone size={16}/></div>
      <div><div style={{fontSize:13,fontWeight:700}}>Send notification</div><div style={{fontSize:10,color:"#687386",marginTop:2}}>Send to all haribhakto or only a project.</div></div>
    </div>
    <label style={{display:"block",marginBottom:14}}><span style={{display:"block",marginBottom:6,fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em"}}>AUDIENCE</span><select value={audience} onChange={e=>setAudience(e.target.value)} className="app-input" style={inputStyle}><option value="all">All haribhakto</option><option value="project">Specific project</option></select></label>
    {audience==="project"&&<label style={{display:"block",marginBottom:14}}><span style={{display:"block",marginBottom:6,fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em"}}>PROJECT</span><select value={projectId} onChange={e=>setProjectId(e.target.value)} className="app-input" style={inputStyle}><option value="">Select project</option>{(projects||[]).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>}
    <Field label="Notification title" value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Important seva update"/>
    <label style={{display:"block",marginBottom:14}}><span style={{display:"block",marginBottom:6,fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em"}}>MESSAGE</span><textarea value={message} onChange={e=>setMessage(e.target.value)} rows={5} placeholder="Write the notification..." className="app-input" style={{...inputStyle,padding:12,resize:"vertical"}}/></label>
    <div style={{display:"flex",justifyContent:"flex-end"}}><Button onClick={send} disabled={busy}>{busy?<Loader2 size={14} className="animate-spin"/>:<Send size={14}/>} {audience==="project"?"Send to project":"Send to all"}</Button></div>
  </div>;
}

