async function sb(path,options={}){
  const r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{...options,headers:{apikey:SUPABASE_ANON_KEY,Authorization:`Bearer ${SUPABASE_ANON_KEY}`,"Content-Type":"application/json",Prefer:options.prefer||"return=representation",...(options.headers||{})}});
  const text=await r.text();
  if(!r.ok){
    let message=text;
    try{const j=JSON.parse(text);message=j?.message||j?.error_description||j?.hint||text}catch{}
    throw new Error(`HTTP ${r.status}: ${message}`);
  }
  if(!text)return null;
  try{return JSON.parse(text)}catch{return text}
}
function uid(p="id"){return `${p}_${Date.now()}_${Math.random().toString(36).slice(2,7)}`}
const supabaseRealtime = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
  realtime: {
    params: { eventsPerSecond: 20 },
  },
  auth: { persistSession: false, autoRefreshToken: false },
});

function subscribeRealtime(channelKey, subscriptions){
  const topics=Object.keys(subscriptions||{});
  if(!topics.length)return()=>{};

  const channel=supabaseRealtime.channel(channelKey);
  topics.forEach(spec=>{
    const [table,filterRaw]=spec.split("|");
    const config={event:"*",schema:"public",table};
    if(filterRaw)config.filter=filterRaw;
    channel.on("postgres_changes",config,payload=>{
      const eventType=payload.eventType;
      const record=payload.new||payload.record||{};
      const old=payload.old||{};
      try{subscriptions[spec]?.({eventType,record,old})}catch(e){console.error("Realtime handler error",e)}
    });
  });

  channel.subscribe(status=>{
    if(status==="SUBSCRIBED") console.debug("Realtime connected:",channelKey);
    if(status==="CHANNEL_ERROR"||status==="TIMED_OUT") console.warn("Realtime status:",channelKey,status);
  });

  return()=>{
    supabaseRealtime.removeChannel(channel);
  };
}

function todayStr(){return new Date().toISOString().slice(0,10)}
function localTodayStr(){const d=new Date();const y=d.getFullYear();const m=String(d.getMonth()+1).padStart(2,"0");const day=String(d.getDate()).padStart(2,"0");return `${y}-${m}-${day}`}
function isFormDateOpen(date){return !!date&&String(date)>=localTodayStr()}
function formatDate(ts){return new Date(`${ts}T00:00:00`).toLocaleDateString(undefined,{day:"numeric",month:"short",year:"numeric"})}
function buildProjectDateRange(start,end){
  const out=[];const s=String(start||"");const e=String(end||s);if(!s)return out;
  const startDate=new Date(`${s}T00:00:00`);const endDate=new Date(`${e}T00:00:00`);
  if(Number.isNaN(startDate.getTime())||Number.isNaN(endDate.getTime()))return [s];
  for(let d=new Date(startDate);d<=endDate;d.setDate(d.getDate()+1))out.push(d.toISOString().slice(0,10));
  return out;
}
const PROFILE_PHOTO_PREFIX="__PROFILE_PHOTO__:";
function extractMemberPhoto(rawTags, explicitPhoto=""){
  if(explicitPhoto)return String(explicitPhoto);
  const tags=Array.isArray(rawTags)?rawTags:[];
  const hit=tags.find(t=>typeof t==="string"&&t.startsWith(PROFILE_PHOTO_PREFIX));
  return hit?hit.slice(PROFILE_PHOTO_PREFIX.length):"";
}
function cleanMemberTags(rawTags){
  return (Array.isArray(rawTags)?rawTags:[]).filter(t=>!(typeof t==="string"&&t.startsWith(PROFILE_PHOTO_PREFIX)));
}
function memberPhotoTag(photo){return photo?`${PROFILE_PHOTO_PREFIX}${photo}`:null}
function mapMemberRow(r){
  const rawTags=Array.isArray(r.Tags)?r.Tags:(Array.isArray(r.tags)?r.tags:[]);
  return {id:String(r.ID??r.id??""),mandal:String(r.Mandal??r.mandal??""),name:String(r.Name??r.name??""),ksetra:String(r.Ksetra??r.ksetra??""),role:String(r.Role??r.role??"member").toLowerCase(),password:String(r.Password??r.password??""),photo:extractMemberPhoto(rawTags,r.Photo??r.photo??r.profile_photo??""),tags:cleanMemberTags(rawTags)}
}
const samePersonId=(a,b)=>String(a??"").trim().toUpperCase()===String(b??"").trim().toUpperCase();

function mapProjectRow(r){
  const assignedMembers=Array.isArray(r.assigned_members)?r.assigned_members:[];
  const assignedKaryakarta=Array.isArray(r.assigned_karyakarta)?r.assigned_karyakarta:[];
  return {
    id:r.id,name:r.name,category:r.category||"",description:r.description||"",coverPhoto:r.coverPhoto||r.cover_photo||"",
    assignedMembers,assignedKaryakarta,eventId:r.event_id||null,projectDate:r.project_date||r.project_start_date||r.date||new Date(r.created_at||Date.now()).toISOString().slice(0,10),projectStartDate:r.project_start_date||r.project_date||r.date||new Date(r.created_at||Date.now()).toISOString().slice(0,10),projectEndDate:r.project_end_date||r.project_start_date||r.project_date||r.date||new Date(r.created_at||Date.now()).toISOString().slice(0,10),projectDates:Array.isArray(r.project_dates)?r.project_dates.map(String).sort():[],enablePhotos:r.enable_photos!==false,enableVideos:r.enable_videos!==false,enableAttendance:r.enable_attendance!==false,enableForms:r.enable_forms!==false,createdBy:r.created_by||"",createdAt:new Date(r.created_at).getTime()
  };
}
function mapEventRow(r){return {id:String(r.id),name:String(r.name||"Untitled event"),description:String(r.description||""),startDate:String(r.start_date||r.event_date||todayStr()),endDate:String(r.end_date||r.start_date||r.event_date||todayStr()),coverPhoto:String(r.cover_photo||""),createdBy:String(r.created_by||""),createdAt:new Date(r.created_at||Date.now()).getTime()}}
function mapProjectCoverRow(r){return {projectId:String(r.project_id),dataUrl:String(r.data_url||"")}}
function mapMediaRow(r){return {id:r.id,type:r.type,dataUrl:r.data_url,projectDate:r.project_date||null,uploadedBy:r.uploaded_by,uploadedAt:new Date(r.uploaded_at).getTime()}}
function mapFormRow(r){return {id:String(r.id),projectId:String(r.project_id),projectDate:r.project_date||null,title:String(r.title||"Untitled form"),description:String(r.description||""),fields:Array.isArray(r.fields)?r.fields:[],allowMultipleResponses:r.allow_multiple_responses===true,createdBy:String(r.created_by||""),createdAt:new Date(r.created_at||Date.now()).getTime()}}
function mapFormResponseRow(r){return {id:String(r.id),formId:String(r.form_id),projectId:String(r.project_id),memberId:String(r.member_id),answers:r.answers&&typeof r.answers==="object"?r.answers:{},submittedAt:new Date(r.submitted_at||Date.now()).getTime()}}
const FORM_FIELD_TYPES=[{value:"short",label:"Short answer"},{value:"long",label:"Long answer"},{value:"number",label:"Number"},{value:"date",label:"Date"},{value:"single",label:"Single choice"},{value:"multi",label:"Multiple choice"},{value:"yesno",label:"Yes / No"}];
function newFormField(){return {id:uid("field"),label:"",type:"short",required:false,options:["Option 1","Option 2"]}}

function compressImage(file,maxDim=1000,quality=.72){return new Promise((resolve,reject)=>{const rd=new FileReader();rd.onload=e=>{const img=new Image();img.onload=()=>{let{width,height}=img;if(width>height&&width>maxDim){height=Math.round(height*maxDim/width);width=maxDim}else if(height>=width&&height>maxDim){width=Math.round(width*maxDim/height);height=maxDim}const c=document.createElement("canvas");c.width=width;c.height=height;c.getContext("2d").drawImage(img,0,0,width,height);resolve(c.toDataURL("image/jpeg",quality))};img.onerror=reject;img.src=e.target.result};rd.onerror=reject;rd.readAsDataURL(file)})}
async function uploadToBucket(file,path){
  // Every media path is unique, so do NOT use x-upsert here.
  // Supabase requires extra SELECT/UPDATE permissions for upsert; a new-object upload only needs INSERT.
  const safePath=path.split("/").map(encodeURIComponent).join("/");
  const endpoint=`${SUPABASE_URL}/storage/v1/object/${encodeURIComponent(MEDIA_BUCKET)}/${safePath}`;
  const headers={
    apikey:SUPABASE_ANON_KEY,
    Authorization:`Bearer ${SUPABASE_ANON_KEY}`,
    "Content-Type":file.type||"application/octet-stream",
    "cache-control":"3600"
  };
  const r=await fetch(endpoint,{method:"POST",headers,body:file});
  const text=await r.text();
  if(!r.ok){
    let message=text;
    try{const j=JSON.parse(text);message=j?.message||j?.error||j?.statusCode||j?.error_description||text}catch{}
    throw new Error(`Storage HTTP ${r.status}: ${message}`);
  }
  return `${SUPABASE_URL}/storage/v1/object/public/${encodeURIComponent(MEDIA_BUCKET)}/${safePath}`;
}

function LoginScreen({onLogin}){
  const[id,setId]=useState("");const[pw,setPw]=useState("");const[busy,setBusy]=useState(false);const[error,setError]=useState("");
  const submit=async()=>{setError("");if(!id||!pw){setError("Enter Haribhakto ID and password.");return}setBusy(true);const e=await onLogin(id,pw);setBusy(false);if(e)setError(e)};
  return <div className="baps-login" style={{minHeight:"100vh",background:"var(--ui-bg)",display:"flex",alignItems:"center",justifyContent:"center",padding:16,...sans}}><div style={{width:"100%",maxWidth:400}}>
    <div style={{marginBottom:26}}><div style={{display:"flex",alignItems:"center",gap:12,color:C.brand}}><div style={{width:44,height:44,borderRadius:14,overflow:"hidden",background:"#fff",border:"1px solid #e5e7eb",boxShadow:"0 6px 18px rgba(18,63,115,.10)",flexShrink:0}}><SafeImage src={APP_LOGO} alt="BAPS Rajkot" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/></div><div><div style={{fontSize:20,fontWeight:700,letterSpacing:"-.03em"}}>BAPS Rajkot</div><div style={{fontSize:10,color:"#687386",marginTop:3}}>Seva · Satsang · Ekta</div></div></div><div style={{fontSize:12,color:"#687386",marginTop:11}}>Sign in to manage seva projects</div></div>
    <div className="baps-login-card" style={{background:"white",padding:24}}>
      <div style={{fontSize:16,fontWeight:700,marginBottom:3}}>Welcome back</div>
      <div style={{fontSize:12,color:"#687386",marginBottom:20}}>Use your Haribhakto ID and password. Haribhakto and karyakartas must also have a registered profile photo.</div>
      <Field label="Haribhakto ID" value={id} onChange={e=>setId(e.target.value.toUpperCase())} autoCapitalize="characters"/>
      <Field label="Password" type="password" value={pw} onChange={e=>setPw(e.target.value)} clearable={false}/>
      <div style={{display:"flex",alignItems:"center",gap:8,padding:"10px 12px",borderRadius:12,background:"#f5f8fb",border:"1px solid #e7edf3",marginBottom:14}}>
        <ImageIcon size={15} color={C.brand}/>
        <span style={{fontSize:10,color:"#687386",lineHeight:1.45}}>Profile photo is required for haribhakto and karyakartas. Admin can sign in without a photo.</span>
      </div>
      {error&&<div style={{fontSize:11,color:"#991b1b",marginBottom:12}}>{error}</div>}
      <Button onClick={submit} disabled={busy} type="button" style={{width:"100%"}}>{busy&&<Loader2 size={14} className="animate-spin"/>}Sign in</Button>
    </div>
  </div></div>;
}

function HomeScreen({currentUser,projects,setView}){
  const[q,setQ]=useState("");
  const mine=projects.filter(p=>currentUser.role==="karyakarta"
    ?(p.assignedKaryakarta||[]).includes(currentUser.id)
    :(p.assignedMembers||[]).includes(currentUser.id));
  const visible=(currentUser.role==="admin"?projects:mine).slice().sort((a,b)=>String(a.projectStartDate||a.projectDate||"").localeCompare(String(b.projectStartDate||b.projectDate||""))||String(a.name||"").localeCompare(String(b.name||"")));
  const searched=q.trim()?visible.filter(p=>`${p.name} ${p.category}`.toLowerCase().includes(q.trim().toLowerCase())):visible;
  const first=currentUser.name.split(" ")[0]||currentUser.id;
  return <main style={{padding:20,...sans}}>
    <div style={{display:"flex",alignItems:"center",gap:12}}>
      <div style={{width:52,height:52,borderRadius:"50%",overflow:"hidden",background:"#eef3f8",border:"1px solid #e0e7ef",flexShrink:0}}>
        {currentUser.photo?<img src={currentUser.photo} alt="" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>:<UserIcon size={24} color={C.brand} style={{margin:13}}/>}
      </div>
      <div style={{minWidth:0,flex:1,paddingRight:48}}>
        <div style={{fontSize:19,fontWeight:700,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>Jai Swaminarayan, {first}</div>
        <div style={{marginTop:5,fontSize:11,color:"#687386"}}>{currentUser.id}</div>
      </div>
    </div>

    <div className="search-field-wrap" style={{marginTop:22}}>
      <Search className="search-icon" size={18} color="#8B97A6"/>
      <input value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")setView("projects")}} placeholder="Search your projects" className={`app-input search-input${q?" has-value":""}`} style={{...inputStyle,borderRadius:18,minHeight:52,paddingRight:52}}/>
      <button type="button" onClick={()=>setView("projects")} title="All projects" style={{position:"absolute",right:6,top:"50%",transform:"translateY(-50%)",width:38,height:38,borderRadius:"50%",border:"none",background:C.brand,color:"#fff",display:"grid",placeItems:"center",cursor:"pointer",zIndex:3}}><SlidersHorizontal size={15}/></button>
    </div>

    <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:10,marginTop:12}}>{[[projects.length,"TOTAL PROJECTS",FolderOpen],[mine.length,currentUser.role==="admin"?"ASSIGNED TO YOU":"MY PROJECTS",HeartHandshake]].map(([n,l,Icon])=><div key={l} className="baps-card" style={{background:"white",padding:16}}><div style={{width:34,height:34,borderRadius:12,background:"var(--ui-blue-soft)",color:C.brand,display:"grid",placeItems:"center",marginBottom:10}}><Icon size={16} strokeWidth={1.6}/></div><div style={{fontSize:26,fontWeight:700,...dataFont,color:C.brand}}>{n}</div><div style={{fontSize:9,color:"#687386",fontWeight:700,letterSpacing:".10em",marginTop:4}}>{l}</div></div>)}</div>

    <div style={{marginTop:28,display:"flex",alignItems:"baseline",justifyContent:"space-between"}}>
      <div style={{fontSize:15,fontWeight:700,color:C.brand}}>{currentUser.role==="admin"?"Recent projects":"Assigned projects"}</div>
      {searched.length>0&&<button onClick={()=>setView("projects")} style={{border:0,background:"transparent",color:"#687386",fontSize:11,fontWeight:600,display:"flex",alignItems:"center",gap:3,cursor:"pointer",...sans}}>See all<ChevronRight size={13}/></button>}
    </div>

    {searched.length===0
      ? <div className="baps-card" style={{background:"white",marginTop:10}}><EmptyState text="No projects available." icon={FolderOpen}/></div>
      : <div className="hide-scroll" style={{display:"flex",gap:14,marginTop:12,overflowX:"auto",paddingBottom:6,paddingRight:2}}>
          {searched.slice(0,8).map(p=>{
            const memberCount=(p.assignedMembers||[]).length, kCount=(p.assignedKaryakarta||[]).length;
            return <div key={p.id} onClick={()=>setView("projectDetail",p.id)} className="baps-card row" style={{minWidth:210,maxWidth:210,background:"white",padding:10,cursor:"pointer",flexShrink:0}}>
              <ProjectCover project={p} height={110} radius={16}>
                <div style={{position:"absolute",left:8,top:8,padding:"3px 9px",borderRadius:999,background:"rgba(255,255,255,.92)",color:C.brand,fontSize:9,fontWeight:700,letterSpacing:".04em"}}>{(p.category||"SEVA").toUpperCase()}</div>
              </ProjectCover>
              <div style={{padding:"10px 4px 2px"}}>
                <div style={{fontSize:13,fontWeight:700,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{p.name}</div>
                <div style={{display:"flex",alignItems:"center",gap:5,marginTop:5,color:"#687386",fontSize:10,...dataFont}}><Users size={11}/>{memberCount} haribhakto · {kCount} karyakarta</div>
              </div>
            </div>;
          })}
        </div>}
  </main>;
}

function MemberPicker({members,assigned,setAssigned,role="member",label,accessNote}){
  const[search,setSearch]=useState("");
  const selectableMembers=useMemo(()=>members.filter(m=>m.role===role),[members,role]);
  const filtered=selectableMembers.filter(m=>`${m.id} ${m.name} ${m.mandal} ${m.ksetra}`.toLowerCase().includes(search.toLowerCase()));
  const availableTags=useMemo(()=>{
    const seen=new Set();
    selectableMembers.forEach(m=>(Array.isArray(m.tags)?m.tags:[]).forEach(t=>{if(t&&!seen.has(t)){seen.add(t)}}));
    return Array.from(seen).sort((a,b)=>a.localeCompare(b));
  },[selectableMembers]);
  const toggle=id=>{const next=assigned.includes(id)?assigned.filter(x=>x!==id):[...assigned,id];setAssigned(next)};
  const toggleTag=tag=>{
    const ids=selectableMembers.filter(m=>(Array.isArray(m.tags)?m.tags:[]).includes(tag)).map(m=>m.id);
    if(!ids.length)return;
    const allSelected=ids.every(id=>assigned.includes(id));
    setAssigned(allSelected?assigned.filter(id=>!ids.includes(id)):Array.from(new Set([...assigned,...ids])));
  };
  const title=label||`ASSIGN ${role==="karyakarta"?"KARYAKARTA":"MEMBERS"}`;
  const isKaryakarta=String(label||"").toUpperCase().includes("KARYAKARTA");
  return <div style={{marginBottom:14}}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
      <div style={{fontSize:10,fontWeight:700,color:"#6b7280",letterSpacing:".12em"}}>{title} · {assigned.length}</div>
      {isKaryakarta&&<span style={{fontSize:9,color:C.brand,fontWeight:700,...sans}}>PROJECT ACCESS</span>}
    </div>
    {accessNote&&<div style={{fontSize:10,color:"#9ca3af",marginBottom:8}}>{accessNote}</div>}

    {availableTags.length>0&&<div style={{marginBottom:8}}>
      <div style={{fontSize:9,fontWeight:700,color:"#7a8796",letterSpacing:".08em",marginBottom:6,...sans}}>SELECT BY TAG</div>
      <div className="hide-scroll" style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:2}}>
        {availableTags.map(tag=>{
          const tagMembers=selectableMembers.filter(m=>(Array.isArray(m.tags)?m.tags:[]).includes(tag));
          const selectedCount=tagMembers.filter(m=>assigned.includes(m.id)).length;
          const active=tagMembers.length>0&&selectedCount===tagMembers.length;
          return <button key={tag} type="button" onClick={()=>toggleTag(tag)} style={{flexShrink:0,border:`1px solid ${active?C.brand:"#e2e8ef"}`,background:active?C.brand:"#fff",color:active?"#fff":"#536174",borderRadius:999,padding:"6px 10px",fontSize:9,fontWeight:700,cursor:"pointer",...sans}}>{tag}{tagMembers.length>0&&<span style={{opacity:.72,marginLeft:4}}>{tagMembers.length}</span>}</button>;
        })}
      </div>
    </div>}

    <div className="search-field-wrap" style={{marginBottom:8}}>
      <Search className="search-icon" size={15} color="#9aa3af"/>
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder={`Search ${isKaryakarta?"karyakarta":"member"} by name`} className="app-input" style={{paddingLeft:52,paddingRight:search?42:17}}/>
      {search&&<button type="button" aria-label="Clear search" className="search-clear" onClick={()=>setSearch("")} style={{width:28,height:28,border:0,borderRadius:8,background:"#f3f4f6",color:"#6b7280",display:"grid",placeItems:"center",cursor:"pointer"}}><X size={14}/></button>}
    </div>
    <div style={{maxHeight:220,overflowY:"auto",border:"1px solid #e5e7eb",borderRadius:6,background:"white"}}>
      {filtered.map(m=><label key={m.id} className="row" style={{display:"flex",alignItems:"center",gap:9,padding:"11px 10px",borderBottom:"1px solid #f3f4f6",cursor:"pointer"}}>
        <input type="checkbox" checked={assigned.includes(m.id)} onChange={()=>toggle(m.id)}/>
        <div style={{minWidth:0,flex:1,fontSize:12,fontWeight:600,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{m.name}</div>
      </label>)}
      {filtered.length===0&&<div style={{padding:14,fontSize:11,color:"#6b7280"}}>{selectableMembers.length===0?`No ${isKaryakarta?"project karyakarta candidates":"haribhakto"} found.`:"No matching people found."}</div>}
    </div>
  </div>;
}
function ProjectForm({initial,members,events=[],onCancel,onSave}){
  const[f,setF]=useState({
    name:initial?.name||"",
    category:initial?.category||"",
    eventId:initial?.eventId||"",
    description:initial?.description||"",
    projectStartDate:initial?.projectStartDate||initial?.projectDate||todayStr(),
    projectEndDate:initial?.projectEndDate||initial?.projectDate||todayStr(),
    projectDates:Array.isArray(initial?.projectDates)&&initial.projectDates.length?initial.projectDates.map(String):buildProjectDateRange(initial?.projectStartDate||initial?.projectDate||todayStr(),initial?.projectEndDate||initial?.projectDate||todayStr()),
    enablePhotos:initial?.enablePhotos!==false,enableVideos:initial?.enableVideos!==false,enableAttendance:initial?.enableAttendance!==false,enableForms:initial?.enableForms!==false,
    assignedMembers:Array.isArray(initial?.assignedMembers)?initial.assignedMembers:[],
    assignedKaryakarta:Array.isArray(initial?.assignedKaryakarta)?initial.assignedKaryakarta:[]
  });
  const[coverFile,setCoverFile]=useState(null);
  const[coverPreview,setCoverPreview]=useState(initial?.coverPhoto||"");
  const[busy,setBusy]=useState(false);
  const toggleProjectDate=d=>setF(s=>({...s,projectDates:s.projectDates.includes(d)?s.projectDates.filter(x=>x!==d):[...s.projectDates,d].sort()}));
  const resetProjectDates=(start,end)=>setF(s=>{const range=buildProjectDateRange(start,end);const kept=s.projectDates.filter(d=>range.includes(d));const next=kept.length?kept:range;return {...s,projectStartDate:start,projectEndDate:end,projectDates:next}});
  const chooseCover=e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith("image/")){appToast("Please select an image file.","error");return}if(file.size>10*1024*1024){appToast("Project photo must be smaller than 10 MB.","error");return}setCoverFile(file);const rd=new FileReader();rd.onload=ev=>setCoverPreview(String(ev.target.result||""));rd.readAsDataURL(file)};

  // Project karyakartas must always be project haribhakto.
  const projectKaryakartaCandidates=useMemo(
    ()=>members.filter(m=>f.assignedMembers.includes(m.id)),
    [members,f.assignedMembers]
  );

  const save=async()=>{
    if(!f.name.trim()){appToast("Project name is required.","error");return}
    if(!f.projectDates.length){appToast("Select at least one active project day.","error");return}
    setBusy(true);
    try{
      const assignedMembers=f.assignedMembers.filter(id=>members.some(m=>m.id===id));
      const assignedKaryakarta=f.assignedKaryakarta.filter(id=>assignedMembers.includes(id));
      await onSave({
        ...f,
        name:f.name.trim(),
        category:f.category.trim(),
        description:f.description.trim(),
        projectDate:f.projectStartDate,
        eventId:f.eventId||null,
        projectStartDate:f.projectStartDate,
        projectEndDate:f.projectEndDate>=f.projectStartDate?f.projectEndDate:f.projectStartDate,
        projectDates:f.projectDates,
        assignedMembers,
        assignedKaryakarta,
        coverFile,
        coverPhoto:coverPreview
      });
    }catch(e){}finally{setBusy(false)}
  };

  // When a member is removed from the project, remove them from karyakarta too.
  const setProjectMembers=next=>{
    setF(s=>({
      ...s,
      assignedMembers:next,
      assignedKaryakarta:s.assignedKaryakarta.filter(id=>next.includes(id))
    }));
  };

  return <div className="project-form-compact">
    <Field label="Project name" value={f.name} onChange={e=>setF({...f,name:e.target.value})}/>
    <Field label="Category" value={f.category} onChange={e=>setF({...f,category:e.target.value})}/>
    {events.length>0&&<label style={{display:"block",marginBottom:14}}><span style={{display:"block",marginBottom:6,fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em"}}>EVENT</span><select value={f.eventId} onChange={e=>setF({...f,eventId:e.target.value})} className="app-input" style={inputStyle}><option value="">No event</option>{events.map(ev=><option key={ev.id} value={ev.id}>{ev.name}</option>)}</select></label>}
    <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:8,marginBottom:10}}>
      <Field label="Project start date" type="date" value={f.projectStartDate} onChange={e=>resetProjectDates(e.target.value,f.projectEndDate<e.target.value?e.target.value:f.projectEndDate)} max="9999-12-31"/>
      <Field label="Project end date" type="date" value={f.projectEndDate} min={f.projectStartDate} onChange={e=>resetProjectDates(f.projectStartDate,e.target.value)} max="9999-12-31"/>
    </div>
    <div style={{border:"1px solid #e5e8ec",borderRadius:12,padding:11,marginBottom:14,background:"#f8fafc"}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8,marginBottom:8}}>
        <div style={{fontSize:10,fontWeight:700,color:C.brand,letterSpacing:".08em",...sans}}>ACTIVE PROJECT DAYS</div>
        <div style={{fontSize:9,color:"#6b7280",...dataFont}}>{f.projectDates.length} selected</div>
      </div>
      <div style={{fontSize:9,color:"#7a8796",marginBottom:8,...sans}}>Uncheck any date on which the project will not run. Those dates will be completely skipped.</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(104px,1fr))",gap:6}}>
        {buildProjectDateRange(f.projectStartDate,f.projectEndDate).map((d,i)=>{
          const active=f.projectDates.includes(d);
          return <button key={d} type="button" onClick={()=>toggleProjectDate(d)} style={{display:"flex",alignItems:"center",gap:7,border:`1px solid ${active?C.brand:"#e1e6ec"}`,background:active?"#eef5fb":"white",color:active?C.brand:"#9aa3af",borderRadius:9,padding:"8px 7px",cursor:"pointer",textAlign:"left",...sans}}><span style={{width:16,height:16,borderRadius:5,border:`1.5px solid ${active?C.brand:"#cbd5df"}`,background:active?C.brand:"white",color:"white",display:"grid",placeItems:"center",flexShrink:0}}>{active&&<Check size={11}/>}</span><span style={{minWidth:0}}><b style={{display:"block",fontSize:8}}>DAY {i+1}</b><span style={{fontSize:9,fontWeight:700}}>{formatDate(d)}</span></span></button>;
        })}
      </div>
    </div>
    <div style={{marginBottom:14}}><div style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em",marginBottom:7}}>PROJECT FEATURES</div><div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:7}}>{[["enablePhotos","Photos",ImageIcon],["enableVideos","Videos",VideoIcon],["enableAttendance","Attendance",CalendarCheck],["enableForms","Forms",ClipboardList]].map(([key,label,Icon])=>{const on=!!f[key];return <button key={key} type="button" onClick={()=>setF(s=>({...s,[key]:!s[key]}))} style={{display:"flex",alignItems:"center",gap:8,padding:"10px 11px",border:`1px solid ${on?C.brand:"#e5e7eb"}`,background:on?"#eef5fb":"white",color:on?C.brand:"#6b7280",borderRadius:9,cursor:"pointer",textAlign:"left",...sans}}><span style={{width:28,height:28,borderRadius:8,display:"grid",placeItems:"center",background:on?C.brand:"#f3f4f6",color:on?"white":"#9aa3af"}}><Icon size={14}/></span><span style={{minWidth:0,flex:1,fontSize:11,fontWeight:700}}>{label}</span><span style={{fontSize:9,fontWeight:800}}>{on?"ON":"OFF"}</span></button>})}</div><div style={{fontSize:9,color:"#7a8796",marginTop:6}}>Only enabled features will be visible inside this project.</div></div><label style={{display:"block",marginBottom:14}}><span style={{display:"block",marginBottom:6,fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em"}}>DESCRIPTION</span><textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})} rows={3} className="app-input" style={{...inputStyle,padding:10,resize:"vertical"}}/></label>

    <label style={{display:"block",marginBottom:14}}><span style={{display:"block",marginBottom:6,fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em"}}>PROJECT PHOTO</span>
      <div style={{border:"1px solid #e5e8ec",borderRadius:16,overflow:"hidden",background:"#f7f9fb"}}>
        <div style={{height:150,position:"relative",background:coverGradient(f.name||"project")}}>
          {coverPreview?<SafeImage src={coverPreview} alt="Project preview" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>:<div style={{height:"100%",display:"grid",placeItems:"center",color:"rgba(255,255,255,.82)"}}><ImageIcon size={42} strokeWidth={1.3}/></div>}
        </div>
        <div style={{padding:10,display:"flex",alignItems:"center",justifyContent:"space-between",gap:8}}>
          <div style={{fontSize:10,color:"#7a8796"}}>{coverPreview?"Project photo selected.":"Add a photo for the project cover."}</div>
          <label htmlFor="project-cover-photo" style={{display:"inline-flex",alignItems:"center",gap:6,padding:"8px 11px",borderRadius:10,background:C.brand,color:"white",fontSize:10,fontWeight:700,cursor:"pointer",whiteSpace:"nowrap",...sans}}><ImageIcon size={13}/>{coverPreview?"Change photo":"Choose photo"}</label>
          <input id="project-cover-photo" type="file" accept="image/*" onChange={chooseCover} style={{display:"none"}}/>
        </div>
      </div>
    </label>

    <MemberPicker
      members={members}
      role="member"
      assigned={f.assignedMembers}
      setAssigned={setProjectMembers}
      label="SELECT HARIBHAKTO"
      accessNote="Select the haribhakto who are part of this project."
    />

    <MemberPicker
      members={projectKaryakartaCandidates}
      role="member"
      assigned={f.assignedKaryakarta}
      setAssigned={a=>setF({...f,assignedKaryakarta:a})}
      label="SELECT KARYAKARTA"
      accessNote="Only selected project haribhakto can be made project karyakartas."
    />

    <div style={{display:"flex",justifyContent:"flex-end",gap:7,marginTop:16}}><Button onClick={save} disabled={busy}>{busy?<Loader2 size={14} className="animate-spin"/>:<Save size={14}/>} {initial?"Save changes":"Create project"}</Button><Button variant="secondary" onClick={onCancel} disabled={busy}>Cancel</Button></div>
  </div>;
}
function EventForm({initial,onCancel,onSave}){
  const[f,setF]=useState({name:initial?.name||"",description:initial?.description||"",startDate:initial?.startDate||todayStr(),endDate:initial?.endDate||initial?.startDate||todayStr()});
  const[busy,setBusy]=useState(false);
  const save=async()=>{if(!f.name.trim()){appToast("Event name is required.","error");return}setBusy(true);try{await onSave({...f,name:f.name.trim(),description:f.description.trim(),endDate:f.endDate<f.startDate?f.startDate:f.endDate});}catch(e){}finally{setBusy(false)}};
  return <div>
    <Field label="Event name" value={f.name} onChange={e=>setF({...f,name:e.target.value})} placeholder="e.g. Diwal"/>
    <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:8,marginBottom:14}}><Field label="Start date" type="date" value={f.startDate} onChange={e=>setF({...f,startDate:e.target.value,endDate:f.endDate<e.target.value?e.target.value:f.endDate})}/><Field label="End date" type="date" min={f.startDate} value={f.endDate} onChange={e=>setF({...f,endDate:e.target.value})}/></div>
    <label style={{display:"block",marginBottom:14}}><span style={{display:"block",marginBottom:6,fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em"}}>DESCRIPTION</span><textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})} rows={4} className="app-input" style={{...inputStyle,padding:10,resize:"vertical"}}/></label>
    <div style={{display:"flex",justifyContent:"flex-end",gap:7}}><Button onClick={save} disabled={busy}>{busy?<Loader2 size={14} className="animate-spin"/>:<Save size={14}/>} {initial?"Save changes":"Create event"}</Button><Button variant="secondary" onClick={onCancel} disabled={busy}>Cancel</Button></div>
  </div>;
}
function EventsScreen({events,projects,members=[],isAdmin,setView,onCreate,onUpdate,onDelete,onEdit,onCreateProject}){
  const[showNew,setShowNew]=useState(false);const[editing,setEditing]=useState(null);const[search,setSearch]=useState("");const[projectEvent,setProjectEvent]=useState(null);
  const filtered=events.filter(e=>`${e.name} ${e.description}`.toLowerCase().includes(search.toLowerCase())).slice().sort((a,b)=>String(a.startDate||"").localeCompare(String(b.startDate||""))||String(a.name||"").localeCompare(String(b.name||"")));
  return <main style={{padding:20,...sans}}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginBottom:14}}><div><div style={{fontSize:19,fontWeight:700,color:C.brand}}>Events</div><div style={{fontSize:11,color:"#687386",marginTop:3}}>{events.length} events</div></div>{isAdmin&&<Button small onClick={()=>setShowNew(true)}><Plus size={14}/>New event</Button>}</div>
    <div className="search-field-wrap" style={{marginBottom:14}}><Search className="search-icon" size={17} color="#8B97A6"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search events" className={`app-input search-input${search?" has-value":""}`}/>{search&&<button type="button" className="search-clear" onClick={()=>setSearch("")}><X size={15}/></button>}</div>
    {filtered.length?<div style={{display:"grid",gap:14}}>{filtered.map(ev=>{
      const ps=projects.filter(p=>p.eventId===ev.id).slice().sort((a,b)=>String(a.projectStartDate||a.projectDate||"").localeCompare(String(b.projectStartDate||b.projectDate||""))||String(a.name||"").localeCompare(String(b.name||"")));
      return <div key={ev.id} className="baps-card" style={{background:"white",padding:14,border:"1px solid #e5e7eb",borderRadius:10}}>
        <div style={{display:"flex",alignItems:"flex-start",gap:10}}>
          <div style={{width:42,height:42,borderRadius:11,background:"var(--ui-blue-soft)",color:C.brand,display:"grid",placeItems:"center",flexShrink:0}}><CalendarDays size={20}/></div>
          <div style={{minWidth:0,flex:1}}>
            <div style={{fontSize:14,fontWeight:700,color:C.brand}}>{ev.name}</div>
            <div style={{fontSize:10,color:"#687386",marginTop:3}}>{formatDate(ev.startDate)}{ev.startDate!==ev.endDate?` – ${formatDate(ev.endDate)}`:""} · {ps.length} {ps.length===1?"project":"projects"}</div>
            {ev.description&&<div style={{fontSize:11,color:"#526174",marginTop:7,lineHeight:1.45}}>{ev.description}</div>}
          </div>
          {isAdmin&&<div style={{display:"flex",gap:3}}><IconButton title="Edit event" onClick={()=>setEditing(ev)}><Pencil size={14}/></IconButton><IconButton title="Delete event" danger onClick={()=>onDelete(ev)}><Trash2 size={14}/></IconButton></div>}
        </div>

        <div style={{marginTop:14,paddingTop:12,borderTop:"1px solid #eef0f3"}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:8,marginBottom:10}}>
            <div style={{fontSize:10,fontWeight:700,color:C.brand,letterSpacing:".08em"}}>PROJECTS · {ps.length}</div>
            {isAdmin&&<Button small onClick={()=>setProjectEvent(ev)}><Plus size={13}/>Add project</Button>}
          </div>
          {ps.length===0
            ? <div style={{padding:"16px 8px",textAlign:"center",fontSize:11,color:"#7a8796"}}>No projects in this event.</div>
            : <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))",gap:16}}>
                {ps.map(p=>{
                  const memberCount=(p.assignedMembers||[]).length, kCount=(p.assignedKaryakarta||[]).length;
                  return <div key={p.id} className="baps-card row" style={{background:"white",padding:12,border:"1px solid #e5e7eb"}}>
                    <div style={{position:"relative"}} onClick={()=>setView("projectDetail",p.id)}>
                      <ProjectCover project={p} height={140} radius={18}>
                        <div style={{position:"absolute",left:10,top:10,padding:"4px 10px",borderRadius:999,background:"rgba(255,255,255,.94)",color:C.brand,fontSize:9,fontWeight:700,letterSpacing:".04em"}}>{(p.category||"SEVA").toUpperCase()}</div>
                      </ProjectCover>
                      <div style={{position:"absolute",inset:0,cursor:"pointer"}}/>
                    </div>
                    <div style={{padding:"12px 4px 4px",display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:8}}>
                      <div style={{minWidth:0,flex:1,cursor:"pointer"}} onClick={()=>setView("projectDetail",p.id)}>
                        <div style={{fontSize:14,fontWeight:700,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{p.name}</div>
                        <div style={{display:"flex",alignItems:"center",gap:4,marginTop:5,color:"#687386",fontSize:11}}><MapPin size={12}/>{p.category||"No category"}</div>
                        <div style={{display:"flex",alignItems:"center",gap:4,marginTop:4,color:"#7a8796",fontSize:10}}><CalendarCheck size={11}/>{p.projectStartDate===p.projectEndDate?formatDate(p.projectStartDate):`${formatDate(p.projectStartDate)} – ${formatDate(p.projectEndDate)}`}</div>
                      </div>
                      {isAdmin&&<IconButton title="Edit project" onClick={()=>onEdit(p)}><Pencil size={14} strokeWidth={1.5}/></IconButton>}
                    </div>
                    <div style={{display:"flex",gap:8,marginTop:10,flexWrap:"wrap"}}>
                      <span style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 10px",borderRadius:999,background:"var(--ui-blue-soft)",color:C.brand,fontSize:10,fontWeight:700,...dataFont}}><Users size={11}/>{memberCount} haribhakto</span>
                      <span style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 10px",borderRadius:999,background:"#F1F2F4",color:"#4b5563",fontSize:10,fontWeight:700,...dataFont}}><HeartHandshake size={11}/>{kCount} karyakarta</span>
                    </div>
                  </div>;
                })}
              </div>}
        </div>
      </div>;
    })}</div>:<EmptyState text="No events found." icon={CalendarDays}/>} 
    <Modal open={showNew} title="New event" description="Create an event and place seva projects inside it." onClose={()=>setShowNew(false)}><EventForm onCancel={()=>setShowNew(false)} onSave={async d=>{await onCreate(d);setShowNew(false)}}/></Modal>
    <Modal open={!!editing} title="Edit event" description="Update event details." onClose={()=>setEditing(null)}><EventForm initial={editing} onCancel={()=>setEditing(null)} onSave={async d=>{await onUpdate(editing,d);setEditing(null)}}/></Modal>
    <Modal open={!!projectEvent} title={`Add project · ${projectEvent?.name||"Event"}`} description="Create a project inside this event. The project uses the same project settings, days, features and haribhakto as the Projects section." onClose={()=>setProjectEvent(null)} wide>
      <ProjectForm members={members} events={events} initial={{eventId:projectEvent?.id||""}} onCancel={()=>setProjectEvent(null)} onSave={async d=>{await onCreateProject(d);setProjectEvent(null)}}/>
    </Modal>
  </main>;
}

function ProjectsScreen({projects,members,events=[],isAdmin,setView,onCreate,onEdit}){
  const[search,setSearch]=useState("");const[showNew,setShowNew]=useState(false);const[cat,setCat]=useState("all");
  const categories=useMemo(()=>Array.from(new Set(projects.map(p=>p.category).filter(Boolean))),[projects]);
  const filtered=projects
    .filter(p=>cat==="all"||p.category===cat)
    .filter(p=>`${p.name} ${p.category} ${p.description}`.toLowerCase().includes(search.toLowerCase()))
    .slice().sort((a,b)=>String(a.projectStartDate||a.projectDate||"").localeCompare(String(b.projectStartDate||b.projectDate||""))||String(a.name||"").localeCompare(String(b.name||"")));
  return <main style={{padding:20,...sans}}>
    <div style={{position:"relative",display:"grid",gridTemplateColumns:"minmax(0,1fr) auto",alignItems:"center",gap:10,marginBottom:16,minHeight:52,paddingRight:isAdmin?52:0}}>
      <div style={{minWidth:0,justifySelf:"start"}}><div style={{fontSize:19,fontWeight:700,color:C.brand}}>Projects</div><div style={{fontSize:11,color:"#687386",marginTop:3}}>{projects.length} seva {projects.length===1?"project":"projects"}</div></div>
      {isAdmin&&<div style={{justifySelf:"end",width:1,height:1,overflow:"hidden"}} aria-hidden="true"/>}
    </div>

    <div className="search-field-wrap" style={{marginBottom:14}}>
      <Search className="search-icon" size={17} color="#8B97A6"/>
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search projects" className={`app-input search-input${search?" has-value":""}`} />
      {search&&<button type="button" aria-label="Clear search" className="search-clear" onClick={()=>setSearch("")}><X size={15}/></button>}
    </div>

    <div className="hide-scroll" style={{display:"flex",gap:8,overflowX:"auto",marginBottom:18,paddingBottom:2}}>
      {["all",...categories].map(c=><button key={c} onClick={()=>setCat(c)} style={{flexShrink:0,border:`1px solid ${cat===c?C.brand:"var(--ui-line)"}`,background:cat===c?C.brand:"#fff",color:cat===c?"#fff":"#374151",borderRadius:999,padding:"8px 16px",fontSize:11,fontWeight:700,cursor:"pointer",...sans}}>{c==="all"?"All types":c}</button>)}
    </div>

    <button type="button" data-new-project-trigger onClick={()=>setShowNew(true)} aria-hidden="true" tabIndex={-1} style={{display:"none"}}/><Modal open={showNew} title="New project" description="Create a seva project, select haribhakto and assign project karyakartas." onClose={()=>setShowNew(false)} wide><ProjectForm members={members} events={events} onCancel={()=>setShowNew(false)} onSave={async d=>{await onCreate(d);setShowNew(false)}}/></Modal>

    {filtered.length===0
      ? <div className="baps-card" style={{background:"white"}}><EmptyState text="No matching projects." icon={FolderOpen}/></div>
      : <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))",gap:16}}>
          {filtered.map(p=>{
            const memberCount=(p.assignedMembers||[]).length, kCount=(p.assignedKaryakarta||[]).length;
            return <div key={p.id} className="baps-card row" style={{background:"white",padding:12}}>
              <div style={{position:"relative"}} onClick={()=>setView("projectDetail",p.id)}>
                <ProjectCover project={p} height={140} radius={18}>
                  <div style={{position:"absolute",left:10,top:10,padding:"4px 10px",borderRadius:999,background:"rgba(255,255,255,.94)",color:C.brand,fontSize:9,fontWeight:700,letterSpacing:".04em"}}>{(p.category||"SEVA").toUpperCase()}</div>
                </ProjectCover>
                <div style={{position:"absolute",inset:0,cursor:"pointer"}}/>
              </div>
              <div style={{padding:"12px 4px 4px",display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:8}}>
                <div style={{minWidth:0,flex:1,cursor:"pointer"}} onClick={()=>setView("projectDetail",p.id)}>
                  <div style={{fontSize:14,fontWeight:700,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{p.name}</div>
                  <div style={{display:"flex",alignItems:"center",gap:4,marginTop:5,color:"#687386",fontSize:11}}><MapPin size={12}/>{p.category||"No category"}</div>{p.eventId&&<div style={{display:"flex",alignItems:"center",gap:4,marginTop:4,color:C.brand,fontSize:10,fontWeight:700}}><CalendarDays size={11}/>{events.find(ev=>ev.id===p.eventId)?.name||"Event"}</div>}<div style={{display:"flex",alignItems:"center",gap:4,marginTop:4,color:"#7a8796",fontSize:10}}><CalendarCheck size={11}/>{p.projectStartDate===p.projectEndDate?formatDate(p.projectStartDate):`${formatDate(p.projectStartDate)} – ${formatDate(p.projectEndDate)}`}</div>
                </div>
                {isAdmin&&<IconButton title="Edit project" onClick={()=>onEdit(p)}><Pencil size={14} strokeWidth={1.5}/></IconButton>}
              </div>
              <div style={{display:"flex",gap:8,marginTop:10,flexWrap:"wrap"}}>
                <span style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 10px",borderRadius:999,background:"var(--ui-blue-soft)",color:C.brand,fontSize:10,fontWeight:700,...dataFont}}><Users size={11}/>{memberCount} haribhakto</span>
                <span style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 10px",borderRadius:999,background:"#F1F2F4",color:"#4b5563",fontSize:10,fontWeight:700,...dataFont}}><HeartHandshake size={11}/>{kCount} karyakarta</span>
              </div>
            </div>;
          })}
        </div>}
  </main>;
}


function FormBuilder({initial,onCancel,onSave}){
  const[f,setF]=useState({title:initial?.title||"",description:initial?.description||"",fields:Array.isArray(initial?.fields)&&initial.fields.length?initial.fields.map(x=>({...x,id:x.id||uid("field"),options:Array.isArray(x.options)?x.options:["Option 1","Option 2"]})): [newFormField()],allowMultipleResponses:initial?.allowMultipleResponses===true});
  const[busy,setBusy]=useState(false);
  const updateField=(id,patch)=>setF(s=>({...s,fields:s.fields.map(x=>x.id===id?{...x,...patch}:x)}));
  const removeField=id=>setF(s=>({...s,fields:s.fields.filter(x=>x.id!==id)}));
  const addField=()=>setF(s=>({...s,fields:[...s.fields,newFormField()]}));
  const save=async()=>{
    if(!f.title.trim()){appToast("Form title is required.","error");return}
    const fields=f.fields.map(x=>({id:x.id,label:String(x.label||"").trim(),type:x.type,required:!!x.required,options:(x.type==="single"||x.type==="multi")?(x.options||[]).map(v=>String(v||"").trim()).filter(Boolean):[]}));
    if(fields.some(x=>!x.label)){appToast("Every question needs a label.","error");return}
    if(fields.some(x=>(x.type==="single"||x.type==="multi")&&x.options.length<2)){appToast("Choice questions need at least two options.","error");return}
    setBusy(true);try{await onSave({...f,title:f.title.trim(),description:f.description.trim(),fields})}catch(e){}finally{setBusy(false)}
  };
  return <div>
    <Field label="Form title" value={f.title} onChange={e=>setF({...f,title:e.target.value})} placeholder="e.g. Seva registration form"/>
    <label style={{display:"block",marginBottom:14}}><span style={{display:"block",marginBottom:6,fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em"}}>DESCRIPTION</span><textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})} rows={2} className="app-input" style={{...inputStyle,padding:10,resize:"vertical"}} placeholder="Optional instructions for haribhakto."/></label>
    <label style={{display:"flex",alignItems:"flex-start",gap:9,padding:"10px 11px",marginBottom:14,border:"1px solid #e5e7eb",borderRadius:9,background:"#f8fafc",cursor:"pointer"}}><input type="checkbox" checked={!!f.allowMultipleResponses} onChange={e=>setF({...f,allowMultipleResponses:e.target.checked})} style={{marginTop:2}}/><span><span style={{display:"block",fontSize:11,fontWeight:700,color:"#374151"}}>ALLOW MULTIPLE RESPONSES</span><span style={{display:"block",fontSize:9,color:"#7a8796",marginTop:3}}>If enabled, a haribhakto can submit this form again and again. Each submission is stored separately.</span></span></label>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}><div style={{fontSize:10,fontWeight:700,color:"#6b7280",letterSpacing:".12em"}}>QUESTIONS · {f.fields.length}</div><Button small variant="secondary" onClick={addField}><Plus size={13}/>Add question</Button></div>
    <div style={{display:"grid",gap:8}}>{f.fields.map((q,i)=><div key={q.id} style={{border:"1px solid #e5e7eb",borderRadius:7,padding:12,background:"#fff"}}>
      <div style={{display:"flex",justifyContent:"space-between",gap:8,alignItems:"center",marginBottom:10}}><div style={{fontSize:10,fontWeight:700,color:"#9ca3af",...dataFont}}>QUESTION {i+1}</div><IconButton title="Remove question" danger onClick={()=>removeField(q.id)} disabled={f.fields.length===1}><Trash2 size={14}/></IconButton></div>
      <Field label="Question" value={q.label} onChange={e=>updateField(q.id,{label:e.target.value})} placeholder="Enter your question"/>
      <SelectField label="Answer type" value={q.type} onChange={e=>updateField(q.id,{type:e.target.value})} options={FORM_FIELD_TYPES}/>
      {(q.type==="single"||q.type==="multi")&&<div style={{marginBottom:12}}><div style={{fontSize:10,fontWeight:700,color:"#6b7280",textTransform:"uppercase",letterSpacing:".12em",marginBottom:7}}>OPTIONS</div>{(q.options||[]).map((op,oi)=><div key={oi} style={{display:"flex",gap:6,marginBottom:6}}><input value={op} onChange={e=>updateField(q.id,{options:(q.options||[]).map((v,j)=>j===oi?e.target.value:v)})} className="app-input" style={{...inputStyle,paddingRight:10}} placeholder={`Option ${oi+1}`}/><IconButton title="Remove option" onClick={()=>updateField(q.id,{options:(q.options||[]).filter((_,j)=>j!==oi)})} disabled={(q.options||[]).length<=2}><X size={14}/></IconButton></div>)}<Button small variant="secondary" onClick={()=>updateField(q.id,{options:[...(q.options||[]),""]})}><Plus size={12}/>Add option</Button></div>}
      <label style={{display:"inline-flex",alignItems:"center",gap:7,fontSize:11,color:"#4b5563",cursor:"pointer"}}><input type="checkbox" checked={!!q.required} onChange={e=>updateField(q.id,{required:e.target.checked})}/>Required</label>
    </div>)}</div>
    <div style={{display:"flex",justifyContent:"flex-end",gap:7,marginTop:16}}><Button onClick={save} disabled={busy}>{busy?<Loader2 size={14} className="animate-spin"/>:<Save size={14}/>} {initial?"Save form":"Create form"}</Button><Button variant="secondary" onClick={onCancel} disabled={busy}>Cancel</Button></div>
  </div>;
}

function FormAnswerInput({question,value,onChange}){
  const v=value??(question.type==="multi"?[]:"");
  if(question.type==="long")return <textarea value={v} onChange={e=>onChange(e.target.value)} rows={3} className="app-input" style={{...inputStyle,padding:10,resize:"vertical"}}/>;
  if(question.type==="number")return <input type="number" value={v} onChange={e=>onChange(e.target.value)} className="app-input" style={{...inputStyle,paddingRight:10}}/>;
  if(question.type==="date")return <input type="date" value={v} onChange={e=>onChange(e.target.value)} className="app-input" style={{...inputStyle,paddingRight:10}}/>;
  if(question.type==="yesno")return <div style={{display:"flex",gap:6}}>{["Yes","No"].map(x=><button key={x} type="button" onClick={()=>onChange(x)} style={{border:`1px solid ${v===x?C.brand:"#e5e7eb"}`,background:v===x?C.brand:"white",color:v===x?"white":"#4b5563",borderRadius:5,padding:"7px 12px",fontSize:11,fontWeight:600,cursor:"pointer"}}>{x}</button>)}</div>;
  if(question.type==="single")return <div style={{display:"grid",gap:6}}>{(question.options||[]).map(x=><label key={x} style={{display:"flex",alignItems:"center",gap:7,fontSize:11,color:"#374151",cursor:"pointer"}}><input type="radio" name={`q-${question.id}`} checked={v===x} onChange={()=>onChange(x)}/>{x}</label>)}</div>;
  if(question.type==="multi")return <div style={{display:"grid",gap:6}}>{(question.options||[]).map(x=>{const a=Array.isArray(v)?v:[];return <label key={x} style={{display:"flex",alignItems:"center",gap:7,fontSize:11,color:"#374151",cursor:"pointer"}}><input type="checkbox" checked={a.includes(x)} onChange={()=>onChange(a.includes(x)?a.filter(y=>y!==x):[...a,x])}/>{x}</label>})}</div>;
  return <input value={v} onChange={e=>onChange(e.target.value)} className="app-input" style={{...inputStyle,paddingRight:10}}/>;
}

function FormFillModal({form,currentUser,onClose,onSubmitted,existing}){
  const[answers,setAnswers]=useState(existing?.answers||{});const[busy,setBusy]=useState(false);
  const[dateTick,setDateTick]=useState(0);
  useEffect(()=>{const id=setInterval(()=>setDateTick(x=>x+1),30000);return()=>clearInterval(id)},[]);
  const formOpen=isFormDateOpen(form.projectDate);
  const submit=async()=>{
    if(!formOpen){appToast("This form is closed because the project date has ended.","info");return}
    for(const q of form.fields){const v=answers[q.id];const empty=Array.isArray(v)?v.length===0:v===undefined||v===null||String(v).trim()==="";if(q.required&&empty){appToast(`Please answer: ${q.label}`,"error");return}}
    setBusy(true);try{
      // Re-check the date immediately before writing so an already-open modal
      // cannot submit after midnight/local project date has ended.
      if(!isFormDateOpen(form.projectDate)){appToast("This form is now closed because the project date has ended.","info");return}
      if(existing&&!form.allowMultipleResponses)await sb(`form_responses?id=eq.${encodeURIComponent(existing.id)}`,{method:"PATCH",body:JSON.stringify({answers,submitted_at:new Date().toISOString()})});
      else await sb("form_responses",{method:"POST",body:JSON.stringify([{id:uid("response"),form_id:form.id,project_id:form.projectId,member_id:currentUser.id,answers,submitted_at:new Date().toISOString()}])});
      appToast(existing&&!form.allowMultipleResponses?"Response updated.":"Response submitted.","success");await onSubmitted();onClose();
    }catch(e){appToast(`Could not save response. ${e?.message||"Unknown database error"}`,"error")}finally{setBusy(false)}
  };
  return <Modal open title={form.title} description={formOpen?(form.description||"Please complete this form."):`${form.description||"Please complete this form."} · Closed` } onClose={onClose} wide><div>{!formOpen&&<div style={{marginBottom:14,padding:"10px 12px",borderRadius:9,background:"#fff7ed",border:"1px solid #fed7aa",color:"#9a3412",fontSize:11,fontWeight:600}}>This form is closed. Responses cannot be submitted or updated after {formatDate(form.projectDate)}.</div>}{form.fields.map((q,i)=><div key={q.id} style={{marginBottom:16}}><div style={{fontSize:11,fontWeight:700,color:"#374151",marginBottom:7}}>{i+1}. {q.label} {q.required&&<span style={{color:"#991b1b"}}>*</span>}</div><FormAnswerInput question={q} value={answers[q.id]} onChange={v=>setAnswers(a=>({...a,[q.id]:v}))}/></div>)}</div><div style={{display:"flex",justifyContent:"flex-end",gap:7,marginTop:10}}><Button onClick={submit} disabled={busy||!formOpen}>{busy?<Loader2 size={14} className="animate-spin"/>:<Check size={14}/>} {existing&&!form.allowMultipleResponses?"Update response":"Submit response"}</Button><Button variant="secondary" onClick={onClose} disabled={busy}>Close</Button></div></Modal>;
}
function FormResponsesModal({form,members,onClose}){
  const[responses,setResponses]=useState([]);
  const[busy,setBusy]=useState(true);
  const[expanded,setExpanded]=useState(null);
  const[memberNames,setMemberNames]=useState({});const[responseSearch,setResponseSearch]=useState("");
  const load=useCallback(async(showLoader=true)=>{
    if(showLoader)setBusy(true);
    try{
      const r=await sb(`form_responses?form_id=eq.${encodeURIComponent(form.id)}&select=*&order=submitted_at.desc`);
      const mapped=(r||[]).map(mapFormResponseRow);
      setResponses(mapped);

      // Load the complete member directory and normalize IDs so names still
      // resolve if the stored member_id has case/whitespace differences.
      const names={};
      try{
        const mr=await sb('members?select=*');
        (mr||[]).forEach(m=>{
          const id=String(m.ID??m.id??'').trim().toUpperCase();
          const name=String(m.Name??m.name??'').trim();
          if(id&&name)names[id]=name;
        });
      }catch(_e){}
      // Guaranteed fallback: resolve every response member_id directly.
      for(const row of mapped){
        const id=String(row.memberId??'').trim();
        const key=id.toUpperCase();
        if(!key||names[key])continue;
        try{
          const one=await sb(`members?ID=eq.${encodeURIComponent(id)}&select=*`);
          const m=one?.[0];
          const name=String(m?.Name??m?.name??'').trim();
          if(name)names[key]=name;
        }catch(_e){}
      }
      setMemberNames(names);
    }catch(e){
      appToast(`Could not load answers. ${e?.message||"Unknown database error"}`,'error');
    }finally{
      if(showLoader)setBusy(false);
    }
  },[form.id]);
  useEffect(()=>{load(true)},[load]);
  useEffect(()=>subscribeRealtime(`answers-${form.id}`,{[`form_responses|form_id=eq.${form.id}`]:()=>load(false)}),[form.id,load]);

  const nameById=useMemo(()=>{
    const out={};
    (members||[]).forEach(m=>{
      const id=String(m.id??'').trim().toUpperCase();
      const name=String(m.name??'').trim();
      if(id&&name)out[id]=name;
    });
    Object.assign(out,memberNames);
    return out;
  },[members,memberNames]);

  const filteredResponses=useMemo(()=>{
    const q=responseSearch.trim().toLowerCase();
    if(!q)return responses;
    return responses.filter(r=>{
      const memberId=String(r.memberId??"").trim();
      const normalizedId=memberId.toUpperCase();
      const matchedMember=(members||[]).find(m=>String(m.id??"").trim().toUpperCase()===normalizedId);
      const displayName=String(matchedMember?.name||nameById[normalizedId]||"").trim();
      const answerText=Object.values(r.answers||{}).flatMap(v=>Array.isArray(v)?v:[v]).join(" " );
      return `${displayName} ${memberId} ${answerText}`.toLowerCase().includes(q);
    });
  },[responses,responseSearch,members,nameById]);

  return <Modal open title={`Answers · ${form.title}`} description={`${responses.length} response${responses.length===1?'':'s'}`} onClose={onClose} wide>
    {!busy&&responses.length>0&&<div style={{position:'relative',marginBottom:10}}><Search size={15} color="#7a8796" style={{position:'absolute',left:10,top:'50%',transform:'translateY(-50%)',pointerEvents:'none'}}/><input value={responseSearch} onChange={e=>setResponseSearch(e.target.value)} placeholder="Search responses by haribhakto, ID or answer" className="app-input" style={{...inputStyle,paddingLeft:34,paddingRight:34,width:'100%',boxSizing:'border-box'}}/>{responseSearch&&<button type="button" onClick={()=>setResponseSearch("")} style={{position:'absolute',right:8,top:'50%',transform:'translateY(-50%)',border:0,background:'transparent',color:'#9aa3af',cursor:'pointer',padding:3}}><X size={14}/></button>}</div>}
    {busy?<div style={{padding:30,textAlign:'center'}}><Loader2 className="animate-spin" size={18} color={C.brand}/></div>:responses.length?<>{filteredResponses.length?<div style={{display:'grid',gap:7}}>{filteredResponses.map(r=>{
      const memberId=String(r.memberId??'').trim();
      const normalizedId=memberId.toUpperCase();
      const matchedMember=(members||[]).find(m=>String(m.id??'').trim().toUpperCase()===normalizedId);
      const displayName=String(matchedMember?.name||nameById[normalizedId]||'').trim()||'Unknown haribhakto';
      return <div key={r.id} style={{border:'1px solid #e5e7eb',borderRadius:7,background:'white'}}>
        <button type="button" onClick={()=>setExpanded(expanded===r.id?null:r.id)} style={{width:'100%',border:0,background:'transparent',padding:'11px 12px',display:'flex',alignItems:'center',gap:9,cursor:'pointer',textAlign:'left'}}>
          <div style={{width:28,height:28,borderRadius:'50%',background:C.brand,color:'white',display:'grid',placeItems:'center',fontSize:9,fontWeight:700}}>{displayName.slice(0,2).toUpperCase()}</div>
          <div style={{minWidth:0,flex:1}}>
            <div style={{fontSize:13,fontWeight:700,color:'#111827',lineHeight:1.25}}>{displayName}</div>
            <div style={{fontSize:10,color:'#6b7280',marginTop:2,...dataFont}}>{memberId} · {new Date(r.submittedAt).toLocaleString()}</div>
          </div>
          <Eye size={15} color="#6b7280"/>
        </button>
        {expanded===r.id&&<div style={{borderTop:'1px solid #f3f4f6',padding:'10px 12px'}}>{form.fields.map(q=><div key={q.id} style={{padding:'8px 0',borderBottom:'1px solid #f9fafb'}}><div style={{fontSize:9,fontWeight:700,color:'#9ca3af',letterSpacing:'.08em',marginBottom:3}}>QUESTION</div><div style={{fontSize:11,fontWeight:600,color:'#374151'}}>{q.label}</div><div style={{fontSize:12,color:"#111827",marginTop:5,whiteSpace:"pre-wrap",textAlign:"left"}}>{Array.isArray(r.answers?.[q.id])?r.answers[q.id].join(', '):String(r.answers?.[q.id]??'—')}</div></div>)}</div>}
      </div>;
    })}</div>:<EmptyState text="No matching responses found." icon={Search}/>}</>:<EmptyState text="No answers submitted yet." icon={ListChecks}/>} 
  </Modal>;
}
function FormsPanel({project,currentUser,members,selectedDate}){
  const[forms,setForms]=useState([]);const[loading,setLoading]=useState(true);const[builder,setBuilder]=useState(null);const[fillForm,setFillForm]=useState(null);const[answersForm,setAnswersForm]=useState(null);const[myResponses,setMyResponses]=useState({});const[myResponseCounts,setMyResponseCounts]=useState({});const[dateTick,setDateTick]=useState(0);
  const normalizedFormRole=String(currentUser?.role||"member").trim().toLowerCase();
  const isAdmin=normalizedFormRole==="admin";const isKaryakarta=normalizedFormRole==="karyakarta"&&(project.assignedKaryakarta||[]).includes(currentUser.id);const isMember=normalizedFormRole==="member";const canManage=isAdmin||isKaryakarta;
  const today=localTodayStr();
  const selectedDateOpen=selectedDate!=="__all__"&&String(selectedDate)>=today;
  useEffect(()=>{const id=setInterval(()=>setDateTick(x=>x+1),30000);return()=>clearInterval(id)},[]);
  const loadForms=useCallback(async(showLoader=false)=>{
    if(showLoader)setLoading(true);
    try{
      const r=await sb(`project_forms?project_id=eq.${encodeURIComponent(project.id)}&select=*&order=created_at.desc`);
      const allForms=(r||[]).map(mapFormRow);
      const fs=selectedDate==="__all__"?allForms:allForms.filter(f=>(f.projectDate||project.projectStartDate||project.projectDate||todayStr())===selectedDate);
      setForms(fs);
      if(isMember){
        if(fs.length){
          const rr=await sb(`form_responses?project_id=eq.${encodeURIComponent(project.id)}&member_id=eq.${encodeURIComponent(currentUser.id)}&select=*`);
          const by={};const counts={};(rr||[]).map(mapFormResponseRow).forEach(x=>{counts[x.formId]=(counts[x.formId]||0)+1;by[x.formId]=x});setMyResponses(by);setMyResponseCounts(counts);
        }else{setMyResponses({});setMyResponseCounts({});}
      }
    }catch(e){console.error("Forms load error:",e);appToast(`Could not load forms. ${e?.message||"Unknown database error"}`,"error")}finally{if(showLoader)setLoading(false)}
  },[project.id,currentUser.id,isMember,selectedDate,project.projectStartDate,project.projectDate,dateTick]);
  useEffect(()=>{loadForms(true)},[loadForms]);
  useEffect(()=>subscribeRealtime(`forms-${project.id}-${currentUser.id}`,{
    [`project_forms|project_id=eq.${project.id}`]:()=>loadForms(false),
    [`form_responses|project_id=eq.${project.id}`]:()=>loadForms(false),
  }),[project.id,currentUser.id,loadForms]);
  const saveForm=async d=>{try{
    if(!canManage){appToast("Haribhakto can only view forms and submit responses.","info");return}
    if(!selectedDate||selectedDate==="__all__"){appToast("Select a project day before creating a form.","info");return}
    if(builder?.id){
      await sb(`project_forms?id=eq.${encodeURIComponent(builder.id)}`,{method:"PATCH",body:JSON.stringify({title:d.title,description:d.description,fields:d.fields,allow_multiple_responses:!!d.allowMultipleResponses})});
    }else{
      await sb("project_forms",{method:"POST",body:JSON.stringify([{id:uid("form"),project_id:project.id,project_date:selectedDate,title:d.title,description:d.description,fields:d.fields,allow_multiple_responses:!!d.allowMultipleResponses,created_by:currentUser.id}])});
    }
    setBuilder(null);await loadForms(false);appToast(builder?.id?"Form updated.":"Form created.","success");
  }catch(e){appToast(`Could not save form. ${e?.message||"Unknown database error"}`,"error");throw e}};
  const deleteForm=async form=>{try{
    if(!canManage){appToast("Haribhakto cannot delete forms.","info");return}await sb(`form_responses?form_id=eq.${encodeURIComponent(form.id)}`,{method:"DELETE"});await sb(`project_forms?id=eq.${encodeURIComponent(form.id)}`,{method:"DELETE"});await loadForms(false);appToast("Form deleted.","success")
  }catch(e){appToast(`Could not delete form. ${e?.message||"Unknown database error"}`,"error")}};
  return <div>
    <div style={{display:"flex",flexWrap:"wrap",alignItems:"center",justifyContent:"space-between",gap:8,marginBottom:10}}><div style={{minWidth:0}}><div style={{fontSize:13,fontWeight:700}}>Forms</div><div style={{fontSize:10,color:"#6b7280",marginTop:3}}>{canManage?"Create forms and review haribhakto answers.":"View forms and submit your answers."}</div></div>{(canManage&&!isMember)&&<Button small disabled={selectedDate==="__all__"} onClick={()=>{if(selectedDate==="__all__"){appToast("Select a project day first.","info");return}setBuilder({})}}><Plus size={13}/>New form</Button>}</div>
    <Modal open={!!builder} title={builder?.id?"Edit form":"New form"} description={builder?.id?`Edit form for ${formatDate(builder.projectDate||selectedDate)}.`:"Build questions that project haribhakto can answer."} onClose={()=>setBuilder(null)} wide><FormBuilder initial={builder?.id?builder:null} onCancel={()=>setBuilder(null)} onSave={saveForm}/></Modal>
    {fillForm&&<FormFillModal form={fillForm} currentUser={currentUser} existing={fillForm.allowMultipleResponses?null:myResponses[fillForm.id]} onClose={()=>setFillForm(null)} onSubmitted={()=>loadForms(false)}/>} 
    {answersForm&&<FormResponsesModal form={answersForm} members={members} onClose={()=>setAnswersForm(null)}/>} 
    {loading?<div style={{padding:28,textAlign:"center"}}><Loader2 className="animate-spin" size={18} color={C.brand}/></div>:forms.length?<div className="baps-card" style={{background:"white",border:"1px solid #e5e7eb",borderRadius:6,overflow:"hidden"}}>{forms.map(f=>{const formOpen=isFormDateOpen(f.projectDate||selectedDate);return <div key={f.id} style={{padding:"12px",borderBottom:"1px solid #f3f4f6",display:"flex",flexWrap:"wrap",alignItems:"flex-start",gap:10,rowGap:10}}>
      <div style={{width:32,height:32,border:"1px solid #e5e7eb",borderRadius:6,display:"grid",placeItems:"center",color:formOpen?C.brand:"#9aa3af",flexShrink:0}}>{formOpen?<FileText size={16}/>:<Lock size={16}/>}</div>
      <div style={{minWidth:180,flex:"1 1 180px"}}><div style={{fontSize:12,fontWeight:700}}>{f.title}</div><div style={{fontSize:10,color:"#6b7280",marginTop:3,lineHeight:1.6}}>{f.fields.length} questions · {f.description||"No description"}{!isMember&&f.allowMultipleResponses&&<span style={{color:C.brand,fontWeight:700}}> · Multiple responses allowed</span>}{!formOpen&&<span style={{color:"#991b1b",fontWeight:700}}> · Closed</span>}</div></div>
      <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",flexShrink:0}}>
        {isMember&&<Button small disabled={!formOpen} onClick={()=>{if(!formOpen){appToast(`Responses closed after ${formatDate(f.projectDate||selectedDate)}.`,"info");return}setFillForm(f)}}>{!formOpen?"Closed":f.allowMultipleResponses?(myResponseCounts[f.id]?`Add response · ${myResponseCounts[f.id]}`:"Add response"):myResponses[f.id]?"Edit response":"Fill form"}</Button>}
        {(canManage&&!isMember)&&<><Button small variant="secondary" onClick={()=>setAnswersForm(f)}><ListChecks size={13}/>Answers</Button><IconButton title="Edit form" onClick={()=>setBuilder(f)}><Pencil size={14}/></IconButton><IconButton title="Delete form" danger onClick={()=>deleteForm(f)}><Trash2 size={14}/></IconButton></>}
      </div>
    </div>})}</div>:<EmptyState text={canManage?"No forms created for this project.":"No forms available for this project."} icon={ClipboardList}/>} 
  </div>;
}

function attendanceExportRows(project, assignedMembers, attendance, selectedDate){
  return assignedMembers.map((m,i)=>{
    const status=attendance?.[selectedDate]?.[m.id]||"Not marked";
    return {
      no:i+1,
      memberId:m.id,
      name:m.name,
      mandal:m.mandal||"",
      ksetra:m.ksetra||"",
      role:m.role||"member",
      status,
      present:status==="present",
      checked:status==="present"?"☑":"☐"
    };
  });
}

async function ensureJsZip(){
  if(window.JSZip)return window.JSZip;
  await new Promise((resolve,reject)=>{
    const existing=document.querySelector('script[data-jszip="1"]');
    if(existing){
      if(window.JSZip){resolve();return}
      existing.addEventListener("load",resolve,{once:true});
      existing.addEventListener("error",reject,{once:true});
      return;
    }
    const script=document.createElement("script");
    script.src="https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js";
    script.dataset.jszip="1";
    script.onload=resolve;script.onerror=reject;
    document.head.appendChild(script);
  });
  if(!window.JSZip)throw new Error("ZIP library could not be loaded.");
  return window.JSZip;
}

async function ensureSheetJsStyle(){
  if(window.XLSX?.utils?.book_new)return window.XLSX;
  await new Promise((resolve,reject)=>{
    const existing=document.querySelector('script[data-xlsx-style="1"]');
    if(existing){
      if(window.XLSX?.utils?.book_new){resolve();return}
      existing.addEventListener("load",resolve,{once:true});
      existing.addEventListener("error",reject,{once:true});
      return;
    }
    const s=document.createElement("script");
    s.src="https://cdn.jsdelivr.net/npm/xlsx-js-style@1.2.0/dist/xlsx.bundle.js";
    s.dataset.xlsxStyle="1";
    s.onload=resolve;s.onerror=reject;
    document.head.appendChild(s);
  });
  if(!window.XLSX?.utils?.book_new)throw new Error("Excel library could not be loaded.");
  return window.XLSX;
}

async function downloadAttendanceExcel(project,assignedMembers,attendance,selectedDate){
  try{
    const XLSX=await ensureSheetJsStyle();
    const JSZip=await ensureJsZip();
    const rows=attendanceExportRows(project,assignedMembers,attendance,selectedDate);
    const data=[
      ["BAPS RAJKOT — SEVA PROJECT MANAGEMENT","","","","","","",""],
      [`${project?.name||"Project"} · ATTENDANCE`,"","","","","","",""],
      [`Date: ${selectedDate||""}`,`Haribhakto: ${rows.length}`,"","","","","",""],
      [],
      ["No.","Haribhakto ID","Name","Mandal","Ksetra","Role","Present","Check Box"],
      ...rows.map(r=>[r.no,r.memberId,r.name,r.mandal,r.ksetra,r.role,!!r.present,!!r.present])
    ];
    const ws=XLSX.utils.aoa_to_sheet(data);
    ws["!merges"]=[{s:{r:0,c:0},e:{r:0,c:7}},{s:{r:1,c:0},e:{r:1,c:7}}];
    ws["!cols"]=[{wch:7},{wch:17},{wch:28},{wch:20},{wch:20},{wch:16},{wch:12},{wch:13}];
    ws["!rows"]=[{hpt:26},{hpt:23},{hpt:19},{hpt:8},{hpt:25},...rows.map(()=>({hpt:22}))];
    const border={top:{style:"thin",color:{rgb:"D9D9D9"}},bottom:{style:"thin",color:{rgb:"D9D9D9"}},left:{style:"thin",color:{rgb:"D9D9D9"}},right:{style:"thin",color:{rgb:"D9D9D9"}}};
    const baseFont={name:"Sora",sz:10,color:{rgb:"202124"}},headerFont={name:"Sora",sz:10,bold:true,color:{rgb:"FFFFFF"}};
    ws["A1"].s={font:{name:"Sora",sz:15,bold:true,color:{rgb:"5C3030"}},alignment:{horizontal:"center",vertical:"center"}};
    ws["A2"].s={font:{name:"Sora",sz:13,bold:true,color:{rgb:"202124"}},alignment:{horizontal:"center",vertical:"center"}};
    ws["A3"].s={font:{name:"Sora",sz:10,color:{rgb:"6B7280"}},alignment:{horizontal:"left",vertical:"center"}};
    ws["B3"].s={font:{name:"Sora",sz:10,color:{rgb:"6B7280"}},alignment:{horizontal:"left",vertical:"center"}};
    for(let c=0;c<8;c++){
      const cell=ws[XLSX.utils.encode_cell({r:4,c})];
      if(cell)cell.s={font:headerFont,fill:{fgColor:{rgb:"5C3030"}},alignment:{horizontal:"center",vertical:"center",wrapText:true},border};
    }
    for(let r=5;r<5+rows.length;r++){
      for(let c=0;c<8;c++){
        const cell=ws[XLSX.utils.encode_cell({r,c})]; if(!cell)continue;
        cell.s={font:baseFont,fill:{fgColor:{rgb:r%2===0?"FAFAFA":"FFFFFF"}},alignment:{horizontal:(c===0||c>=6)?"center":"left",vertical:"center"},border};
      }
      // Present is a normal Boolean TRUE/FALSE column.
      const presentCell=ws[XLSX.utils.encode_cell({r,c:6})];
      if(presentCell){
        presentCell.t="b";presentCell.v=!!rows[r-5].present;
        presentCell.s={font:{name:"Sora",sz:10,bold:true,color:{rgb:rows[r-5].present?"166534":"991B1B"}},fill:{fgColor:{rgb:r%2===0?"FAFAFA":"FFFFFF"}},alignment:{horizontal:"center",vertical:"center"},border};
      }
      // Check Box column also stores TRUE/FALSE. It will receive native Excel Checkbox formatting below.
      const checkboxCell=ws[XLSX.utils.encode_cell({r,c:7})];
      if(checkboxCell){
        checkboxCell.t="b";checkboxCell.v=!!rows[r-5].present;
        checkboxCell.s={font:{name:"Sora",sz:10,color:{rgb:"202124"}},fill:{fgColor:{rgb:r%2===0?"FAFAFA":"FFFFFF"}},alignment:{horizontal:"center",vertical:"center"},border};
      }
    }
    const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,"Attendance");
    wb.Props={Title:`${project?.name||"Project"} Attendance`,Subject:"Project attendance",Author:"BAPS Rajkot Seva Project Management"};
    const safe=String(project?.name||"Project").replace(/[\\/:*?"<>|]/g,"_");
    const bytes=XLSX.write(wb,{bookType:"xlsx",type:"array"});
    const zip=await JSZip.loadAsync(bytes);
    const ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
    const fns="http://schemas.microsoft.com/office/spreadsheetml/2022/featurepropertybag";
    const relns="http://schemas.openxmlformats.org/package/2006/relationships";
    const contentType='<Override PartName="/xl/featurePropertyBag/featurePropertyBag.xml" ContentType="application/vnd.ms-excel.featurepropertybag+xml"/>';
    const relsPath="xl/_rels/workbook.xml.rels";
    let rels=await zip.file(relsPath).async("string");
    if(!rels.includes("FeaturePropertyBag")){
      const idMatch=[...rels.matchAll(/Id="(rId\\d+)"/g)].map(m=>parseInt(m[1].slice(3),10)).filter(Number.isFinite);
      const nextId=`rId${(idMatch.length?Math.max(...idMatch):0)+1}`;
      rels=rels.replace('</Relationships>',`<Relationship Id="${nextId}" Type="http://schemas.microsoft.com/office/2022/11/relationships/FeaturePropertyBag" Target="featurePropertyBag/featurePropertyBag.xml"/></Relationships>`);
      zip.file(relsPath,rels);
    }
    let ct=await zip.file("[Content_Types].xml").async("string");
    if(!ct.includes("featurepropertybag"))ct=ct.replace('</Types>',contentType+'</Types>');
    zip.file("[Content_Types].xml",ct);
    const fp=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<FeaturePropertyBags xmlns="${fns}"><bag type="Checkbox"/><bag type="XFControls"><bagId k="CellControl">0</bagId></bag><bag type="XFComplement"><bagId k="XFControls">1</bagId></bag><bag type="XFComplements" extRef="XFComplementsMapperExtRef"><a k="MappedFeaturePropertyBags"><bagId>2</bagId></a></bag></FeaturePropertyBags>`;
    zip.file("xl/featurePropertyBag/featurePropertyBag.xml",fp);
    const stylesPath="xl/styles.xml";
    let styles=await zip.file(stylesPath).async("string");
    const checkboxXf='<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"><extLst><ext xmlns:xfpb="http://schemas.microsoft.com/office/spreadsheetml/2022/featurepropertybag" uri="{C7286773-470A-42A8-94C5-96B5CB345126}"><xfpb:xfComplement i="0"/></ext></extLst></xf>';
    const cellXfsMatch=styles.match(/<cellXfs[^>]*>([\s\S]*?)<\/cellXfs>/);
    const existingXfs=cellXfsMatch?(cellXfsMatch[1].match(/<xf /g)||[]):[];
    const checkboxStyleId=existingXfs.length;
    if(!styles.includes('C7286773-470A-42A8-94C5-96B5CB345126'))styles=styles.replace('</cellXfs>',checkboxXf+'</cellXfs>');
    zip.file(stylesPath,styles);
    const sheetPath="xl/worksheets/sheet1.xml";
    let sheet=await zip.file(sheetPath).async("string");
    // Apply the checkbox cell style to H6:H(last row), where H is the Check Box column.
    const last=5+rows.length;
    for(let rr=6;rr<=last;rr++){
      const ref=`H${rr}`;
      const re=new RegExp(`<c([^>]*\\br="${ref}"[^>]*)>`);
      sheet=sheet.replace(re,(m,attrs)=>attrs.includes(' s=')?`<c${attrs.replace(/ s="\\d+"/,' s="'+checkboxStyleId+'"')}>`:`<c${attrs} s="${checkboxStyleId}">`);
    }
    zip.file(sheetPath,sheet);
    const blob=await zip.generateAsync({type:"blob",mimeType:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});
    const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`${safe}_Attendance_${selectedDate||"date"}.xlsx`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
    appToast("Attendance Excel downloaded with native Excel checkboxes.","success");
  }catch(e){console.error("Attendance Excel error:",e);appToast(`Could not create Excel. ${e?.message||"Unknown error"}`,"error");}
}

async function ensureJsPdf(){
  if(window.jspdf?.jsPDF)return window.jspdf.jsPDF;
  await new Promise((resolve,reject)=>{
    const existing=document.querySelector('script[data-jspdf="1"]');
    if(existing){existing.addEventListener("load",resolve,{once:true});existing.addEventListener("error",reject,{once:true});return}
    const s=document.createElement("script");
    s.src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
    s.dataset.jspdf="1";s.onload=resolve;s.onerror=reject;document.head.appendChild(s);
  });
  if(!window.jspdf?.jsPDF)throw new Error("PDF library could not be loaded.");
  return window.jspdf.jsPDF;
}

async function downloadAttendancePdf(project,assignedMembers,attendance,selectedDate){
  try{
    const jsPDF=await ensureJsPdf();
    const rows=attendanceExportRows(project,assignedMembers,attendance,selectedDate);
    const doc=new jsPDF({orientation:"landscape",unit:"mm",format:"a4",compress:true});
    const W=doc.internal.pageSize.getWidth(),H=doc.internal.pageSize.getHeight();
    const M=8;

    // Load the actual Sora TTF files. jsPDF cannot use WOFF/WOFF2 as a TTF,
    // so the previous implementation could silently fall back to Helvetica.
    const loadTtfAsBase64=async(url)=>{
      const res=await fetch(url,{mode:"cors",cache:"force-cache"});
      if(!res.ok)throw new Error(`Sora font download failed (${res.status})`);
      const buf=await res.arrayBuffer();
      const bytes=new Uint8Array(buf);
      let binary="";
      const chunk=0x8000;
      for(let i=0;i<bytes.length;i+=chunk){
        binary+=String.fromCharCode(...bytes.subarray(i,i+chunk));
      }
      return btoa(binary);
    };

    let sora=false;
    try{
      const base="https://raw.githubusercontent.com/sora-xor/sora-font/master/fonts/ttf/v2.1beta/";
      const [regular,bold]=await Promise.all([
        loadTtfAsBase64(base+"Sora-Regular.ttf"),
        loadTtfAsBase64(base+"Sora-Bold.ttf")
      ]);
      doc.addFileToVFS("Sora-Regular.ttf",regular);
      doc.addFont("Sora-Regular.ttf","Sora","normal");
      doc.addFileToVFS("Sora-Bold.ttf",bold);
      doc.addFont("Sora-Bold.ttf","Sora","bold");
      sora=true;
    }catch(fontErr){
      console.warn("Sora PDF font could not be embedded; fallback used.",fontErr);
    }

    const font=(weight="normal")=>doc.setFont(sora?"Sora":"helvetica",weight);
    const brand=[92,48,48],ink=[31,35,40],muted=[107,114,128];
    const border=[226,220,216],paper=[255,255,255],soft=[250,247,245];
    const green=[22,101,52],red=[153,27,27];

    const drawCheckbox=(x,y,size,checked)=>{
      doc.setFillColor(255,255,255);
      doc.setDrawColor(...brand);
      doc.setLineWidth(.55);
      doc.roundedRect(x,y,size,size,1.1,1.1,"FD");
      if(checked){
        doc.setDrawColor(...brand);
        doc.setLineWidth(1.05);
        doc.line(x+1.7,y+size*.52,x+size*.43,y+size-1.8);
        doc.line(x+size*.43,y+size-1.8,x+size-1.5,y+1.8);
      }
    };

    const presentCount=rows.filter(r=>r.present).length;
    const absentCount=rows.length-presentCount;

    // Premium header
    doc.setFillColor(...brand);
    doc.roundedRect(M,8,W-2*M,30,3,3,"F");
    font("bold");doc.setFontSize(16);doc.setTextColor(255,255,255);
    doc.text(String(project.name||"Project"),M+7,19);
    font("normal");doc.setFontSize(8.5);doc.setTextColor(244,235,232);
    doc.text("ATTENDANCE REGISTER",M+7,25);
    doc.text(`Date: ${selectedDate}`,M+7,30.5);

    // Summary boxes
    const stats=[
      ["TOTAL",rows.length,ink],
      ["PRESENT",presentCount,green],
      ["ABSENT",absentCount,red]
    ];
    let sx=W-M-83;
    stats.forEach(([label,value,col])=>{
      doc.setFillColor(255,255,255);
      doc.roundedRect(sx,12,24,20,2.5,2.5,"F");
      font("bold");doc.setFontSize(11);doc.setTextColor(...col);
      doc.text(String(value),sx+12,21,{align:"center"});
      font("normal");doc.setFontSize(5.7);doc.setTextColor(...muted);
      doc.text(label,sx+12,27,{align:"center"});
      sx+=27;
    });

    const headerH=10,rowH=13.5,top=44;
    const cols=[
      ["NO.",11],["MEMBER ID",35],["NAME",65],["MANDAL",43],
      ["KSETRA",43],["ROLE",28],["PRESENT",28],["CHECK BOX",28]
    ];
    const total=cols.reduce((a,c)=>a+c[1],0);
    const scale=(W-2*M)/total;
    let y=top;

    const drawTableHeader=()=>{
      let x=M;
      doc.setFillColor(...brand);
      doc.setDrawColor(...brand);
      font("bold");doc.setFontSize(7.1);doc.setTextColor(255,255,255);
      cols.forEach(([label,w])=>{
        const ww=w*scale;
        doc.rect(x,y,ww,headerH,"FD");
        doc.text(label,x+ww/2,y+6.5,{align:"center"});
        x+=ww;
      });
      y+=headerH;
    };

    const fitText=(value,maxChars)=>{
      const s=String(value??"");
      return s.length>maxChars?s.slice(0,maxChars-1)+"…":s;
    };

    const drawRow=(r)=>{
      if(y+rowH>H-13){
        doc.addPage();
        y=13;
        drawTableHeader();
      }

      let x=M;
      const values=[
        r.no,r.memberId,r.name,r.mandal,r.ksetra,r.role,
        r.present?"TRUE":"FALSE",""
      ];

      cols.forEach(([_,w],i)=>{
        const ww=w*scale;
        doc.setFillColor(...(r.no%2===0?soft:paper));
        doc.setDrawColor(...border);
        doc.setLineWidth(.25);
        doc.rect(x,y,ww,rowH,"FD");

        if(i===7){
          drawCheckbox(x+ww/2-3.5,y+2.75,7,r.present);
        }else{
          const center=i===0||i===6;
          font(i===6?"bold":"normal");
          doc.setFontSize(i===6?7.1:7.0);
          if(i===6)doc.setTextColor(...(r.present?green:red));
          else doc.setTextColor(...ink);

          const maxChars=Math.max(5,Math.floor(ww/(i===2?1.75:2.05)));
          const v=fitText(values[i],maxChars);
          doc.text(v,center?x+ww/2:x+2.2,y+8.4,{align:center?"center":"left"});
        }
        x+=ww;
      });
      y+=rowH;
    };

    drawTableHeader();
    rows.forEach(drawRow);

    // Footer
    font("normal");doc.setFontSize(6.3);doc.setTextColor(...muted);
    doc.text(
      `BAPS Rajkot Seva Project Management  •  Generated ${new Date().toLocaleString()}`,
      M,H-5
    );
    doc.text(
      `Page ${doc.internal.getNumberOfPages()}`,
      W-M,H-5,{align:"right"}
    );

    const safe=String(project.name||"Project").replace(/[^a-z0-9_-]+/gi,"_");
    doc.save(`${safe}_Attendance_${selectedDate}.pdf`);
    appToast(sora?"Attendance PDF downloaded in Sora font.":"Attendance PDF downloaded. Sora font could not be loaded.","success");
  }catch(e){
    console.error("Attendance PDF error:",e);
    appToast(`Could not create PDF. ${e?.message||"Unknown error"}`,"error");
  }
}

function ProjectDetail({project,currentUser,members,events=[],setView,refreshProjects}){
  const[descOpen,setDescOpen]=useState(false);
  const normalizedRole=String(currentUser?.role||"member").trim().toLowerCase();
  const isReadOnlyMember=normalizedRole==="member";
  const[tab,setTab]=useState("photos");const[media,setMedia]=useState([]);const[attendance,setAttendance]=useState({});const[selectedDate,setSelectedDate]=useState("__all__");const[attendanceSearch,setAttendanceSearch]=useState("");const[draft,setDraft]=useState({});const[uploading,setUploading]=useState(false);const[lightbox,setLightbox]=useState(null);const[deleteMediaTarget,setDeleteMediaTarget]=useState(null);const[deleteMediaBusy,setDeleteMediaBusy]=useState(false);const photoInputRef=useRef(null);const videoInputRef=useRef(null);
  const projectStartDate=project.projectStartDate||project.projectDate||todayStr();
  const projectEndDate=project.projectEndDate||projectStartDate;
  const projectDates=useMemo(()=>{
    const saved=Array.isArray(project.projectDates)?project.projectDates.map(String).filter(Boolean).sort():[];
    return saved.length?saved:buildProjectDateRange(projectStartDate,projectEndDate);
  },[project.projectDates,projectStartDate,projectEndDate]);
  const isAllProject=selectedDate==="__all__";
  const enabledTabs=useMemo(()=>[{k:"photos",l:"Photos",i:ImageIcon,on:project.enablePhotos},{k:"videos",l:"Videos",i:VideoIcon,on:project.enableVideos},{k:"attendance",l:"Attendance",i:CalendarCheck,on:project.enableAttendance},{k:"forms",l:"Forms",i:ClipboardList,on:project.enableForms}].filter(x=>x.on&&((x.k!=="attendance")||normalizedRole!=="member")),[project.enablePhotos,project.enableVideos,project.enableAttendance,project.enableForms,normalizedRole]);
  useEffect(()=>{if(!enabledTabs.some(x=>x.k===tab))setTab(enabledTabs[0]?.k||"photos")},[enabledTabs,tab]);
  const featureEnabled={photos:project.enablePhotos!==false,videos:project.enableVideos!==false,attendance:project.enableAttendance!==false,forms:project.enableForms!==false};
  const visibleTabs=useMemo(()=>[
    featureEnabled.photos?{k:"photos",l:"Photos",i:ImageIcon}:null,
    featureEnabled.videos?{k:"videos",l:"Videos",i:VideoIcon}:null,
    featureEnabled.attendance&&normalizedRole!=="member"?{k:"attendance",l:"Attendance",i:CalendarCheck}:null,
    featureEnabled.forms?{k:"forms",l:"Forms",i:ClipboardList}:null
  ].filter(Boolean),[featureEnabled.photos,featureEnabled.videos,featureEnabled.attendance,featureEnabled.forms,normalizedRole]);
  const enabledTabKeys=useMemo(()=>visibleTabs.map(x=>x.k),[visibleTabs]);
  useEffect(()=>{if(!isAllProject&&!projectDates.includes(selectedDate))setSelectedDate("__all__")},[projectDates,selectedDate,isAllProject]);
  useEffect(()=>{if(!featureEnabled[tab])setTab(enabledTabKeys[0]||"photos")},[tab,enabledTabKeys,featureEnabled.photos,featureEnabled.videos,featureEnabled.attendance,featureEnabled.forms]);
  const isProjectKaryakarta=(project.assignedKaryakarta||[]).includes(currentUser.id);
  const isProjectMember=(project.assignedMembers||[]).includes(currentUser.id);
  const hasProjectAccess=currentUser.role==="admin"||isProjectKaryakarta||isProjectMember;
  const canEdit=normalizedRole==="admin"||(normalizedRole==="karyakarta"&&isProjectKaryakarta);
  const assignedMembers=useMemo(()=>members.filter(m=>(project.assignedMembers||[]).includes(m.id)),[members,project.assignedMembers]);
  const assignedK=useMemo(()=>members.filter(m=>(project.assignedKaryakarta||[]).includes(m.id)),[members,project.assignedKaryakarta]);
  const filteredAttendanceMembers=useMemo(()=>{
    const q=attendanceSearch.trim().toLowerCase();
    if(!q)return assignedMembers;
    return assignedMembers.filter(m=>`${m.id} ${m.name} ${m.mandal} ${m.ksetra}`.toLowerCase().includes(q));
  },[assignedMembers,attendanceSearch]);
  const loadMedia=useCallback(async()=>{try{const r=await sb(`project_media?project_id=eq.${project.id}&select=*&order=uploaded_at.desc`);const mapped=(r||[]).map(mapMediaRow);const coverUrl=String(project.coverPhoto||"");setMedia(mapped.filter(m=>!(m.type==="photo"&&coverUrl&&String(m.dataUrl||"")===coverUrl)&&(isAllProject||((m.projectDate||projectStartDate)===selectedDate))))}catch(e){console.error(e)}},[project.id,project.coverPhoto,selectedDate,projectStartDate,isAllProject]);
  const loadAttendance=useCallback(async()=>{try{const r=await sb(`attendance?project_id=eq.${project.id}&select=*`);const by={};(r||[]).forEach(x=>{if(!by[x.date])by[x.date]={};by[x.date][x.username]=x.status});setAttendance(by);setDraft(isAllProject?{}:(by[selectedDate]||{}))}catch(e){console.error(e)}},[project.id,selectedDate,isAllProject]);
  useEffect(()=>{loadMedia()},[loadMedia]);
  useEffect(()=>{loadAttendance()},[loadAttendance]);
  // True Supabase Realtime: media/attendance changes arrive immediately from the database.
  useEffect(()=>subscribeRealtime(`project-${project.id}`,{
    [`project_media|project_id=eq.${project.id}`]:()=>loadMedia(),
    ...(normalizedRole!=="member"?{[`attendance|project_id=eq.${project.id}`]:()=>loadAttendance()}:{})
  }),[project.id,currentUser.role,loadMedia,loadAttendance]);
  const saveAttendance=async()=>{if(!featureEnabled.attendance){appToast("Attendance is disabled for this project.","info");return}if(isAllProject){appToast("Select a project day before saving attendance.","info");return}const rows=Object.entries(draft).filter(([,status])=>status).map(([username,status])=>({project_id:project.id,date:selectedDate,username,status}));if(!rows.length){appToast("Select Present or Absent first.","error");return}try{await sb("attendance?on_conflict=project_id,date,username",{method:"POST",prefer:"resolution=merge-duplicates,return=representation",body:JSON.stringify(rows)});await loadAttendance();appToast("Attendance saved.","success")}catch(e){console.error("Attendance save error:",e);appToast(`Could not save attendance. ${e?.message||"Unknown database error"}`,"error")}};
  const uploadPhoto=async e=>{
  if(!featureEnabled.photos){appToast("Photos are disabled for this project.","info");if(e?.target)e.target.value="";return}
  if(isReadOnlyMember){appToast("Haribhakto can only view project photos.","info");if(e?.target)e.target.value="";return}
  const file=e.target.files?.[0];if(!file)return;if(isAllProject){appToast("Select a project day before adding photos.","info");e.target.value="";return}setUploading(true);
  try{
    const d=await compressImage(file);
    let url;
    try{
      const blob=await (await fetch(d)).blob();
      url=await uploadToBucket(blob,`${project.id}/${uid("photo")}.jpg`);
    }catch(storageErr){
      // Small compressed photos can still be stored directly in project_media.
      // This keeps photo upload usable while Storage policies are being fixed.
      if(d.length>6500000) throw storageErr;
      url=d;
      appToast("Storage upload failed; saving the compressed photo directly.","info");
    }
    await sb("project_media",{method:"POST",body:JSON.stringify([{project_id:project.id,type:"photo",project_date:selectedDate,data_url:url,uploaded_by:currentUser.id}])});
    await loadMedia();
    appToast("Photo added.","success");
  }catch(err){
    console.error("Photo upload error:",err);
    appToast(`Could not upload photo. ${err?.message||"Unknown upload error"}`,"error");
  }finally{setUploading(false);e.target.value="";}
};
  const uploadVideo=async e=>{
  if(!featureEnabled.videos){appToast("Videos are disabled for this project.","info");if(e?.target)e.target.value="";return}
  if(isReadOnlyMember){appToast("Haribhakto can only view project videos.","info");if(e?.target)e.target.value="";return}
  const file=e.target.files?.[0];if(!file)return;
  if(isAllProject){appToast("Select a project day before adding videos.","info");e.target.value="";return}
  // Standard Supabase uploads are intended for smaller files. Keep the app fallback reliable.
  if(file.size>50*1024*1024){appToast("Video must be under 50MB.","error");e.target.value="";return}
  setUploading(true);
  try{
    const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,"_");
    let url;
    try{
      url=await uploadToBucket(file,`${project.id}/${uid("video")}-${safeName}`);
    }catch(storageErr){
      // Small clips can fall back to a data URL. Larger videos must use Storage.
      if(file.size>6500000) throw storageErr;
      url=await new Promise((resolve,reject)=>{
        const rd=new FileReader();
        rd.onload=()=>resolve(rd.result);
        rd.onerror=()=>reject(new Error("Could not read video"));
        rd.readAsDataURL(file);
      });
      appToast("Storage upload failed; saving the small video directly.","info");
    }
    await sb("project_media",{method:"POST",body:JSON.stringify([{project_id:project.id,type:"video",project_date:selectedDate,data_url:url,uploaded_by:currentUser.id}])});
    await loadMedia();
    appToast("Video added.","success");
  }catch(err){
    console.error("Video upload error:",err);
    appToast(`Could not upload video. ${err?.message||"Unknown upload error"}`,"error");
  }finally{setUploading(false);e.target.value="";}
};
  const deleteMedia=async()=>{
    if(isReadOnlyMember){appToast("Haribhakto cannot delete project media.","info");return}
    const item=deleteMediaTarget;
    if(!item)return;
    setDeleteMediaBusy(true);
    try{
      await sb(`project_media?id=eq.${encodeURIComponent(item.id)}`,{method:"DELETE"});
      setDeleteMediaTarget(null);
      setLightbox(null);
      await loadMedia();
      appToast(`${item.type==="photo"?"Photo":"Video"} deleted.`,"success");
    }catch(e){
      appToast(`Could not delete ${item.type==="photo"?"photo":"video"}. ${e?.message||"Unknown database error"}`,"error");
    }finally{setDeleteMediaBusy(false)}
  };
  const photos=media.filter(m=>m.type==="photo"),videos=media.filter(m=>m.type==="video"),galleryMedia=photos.length+videos.length;
  if(!hasProjectAccess){
    return <div><TopBar title={project.name} subtitle={project.category||"Seva project"} onBack={()=>setView("projects")}/><main style={{padding:20,...sans}}><EmptyState text="You are not assigned to this project." icon={Lock}/></main></div>;
  }
  if(currentUser.role==="karyakarta" && !isProjectKaryakarta){
    return <div><TopBar title={project.name} subtitle={project.category||"Seva project"} onBack={()=>setView("projects")}/><main style={{padding:20,...sans}}><EmptyState text="You are not assigned to this project." icon={Lock}/></main></div>;
  }
  const desc=project.description||"";
  const descIsLong=desc.length>150;
  return <div>
    <div style={{position:"relative"}}>
      <ProjectCover project={project} height={210} radius={0}>
        <button title="Back" onClick={()=>setView("projects")} style={{position:"absolute",left:16,top:"calc(env(safe-area-inset-top,0px) + 16px)",width:40,height:40,borderRadius:"50%",border:"none",background:"rgba(255,255,255,.94)",color:C.brand,display:"grid",placeItems:"center",cursor:"pointer",boxShadow:"0 6px 18px rgba(24,39,58,.12)"}}><ChevronLeft size={18}/></button>
      </ProjectCover>
      <div className="baps-card" style={{background:"white",margin:"-30px 16px 0",position:"relative",padding:16}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10}}>
          <div style={{minWidth:0}}>
            <div style={{fontSize:19,fontWeight:700,color:C.brand,lineHeight:1.15}}>{project.name}</div>
            <div style={{display:"flex",alignItems:"center",gap:4,marginTop:6,color:"#687386",fontSize:12}}><MapPin size={13}/>{project.category||"Seva project"}</div>
            {project.eventId&&<div style={{display:"flex",alignItems:"center",gap:4,marginTop:5,color:C.brand,fontSize:10,fontWeight:700}}><CalendarDays size={12}/>{events.find(ev=>ev.id===project.eventId)?.name||"Event"}</div>}
          </div>
          <span style={{flexShrink:0,display:"inline-flex",alignItems:"center",gap:5,padding:"6px 12px",borderRadius:999,background:"var(--ui-blue-soft)",color:C.brand,fontSize:11,fontWeight:700,...dataFont}}><Users size={12}/>{assignedMembers.length}</span>
        </div>

        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,marginTop:12,padding:"9px 11px",border:"1px solid #e5e8ec",borderRadius:12,background:"#f8fafc"}}>
          <div style={{display:"flex",alignItems:"center",gap:7,color:C.brand,fontSize:10,fontWeight:700}}><CalendarCheck size={14}/> PROJECT DAYS</div>
          <div style={{fontSize:11,fontWeight:700,color:C.brand,...dataFont}}>{projectDates.length} {projectDates.length===1?"day":"days"}</div>
        </div>

        <div style={{display:"flex",gap:6,flexWrap:"wrap",marginTop:10}}>{[["photos","Photos",ImageIcon],["videos","Videos",VideoIcon],["attendance","Attendance",CalendarCheck],["forms","Forms",ClipboardList]].map(([k,label,Icon])=>featureEnabled[k]&&<span key={k} style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 8px",borderRadius:999,background:"#f1f2f4",color:"#526174",fontSize:9,fontWeight:700}}><Icon size={11}/>{label}</span>)}</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap",marginTop:14}}>
          <span style={{display:"inline-flex",alignItems:"center",gap:6,padding:"6px 12px",borderRadius:999,background:"#F1F2F4",color:"#4b5563",fontSize:10,fontWeight:700,...dataFont}}><Users size={12}/>{assignedMembers.length} haribhakto</span>
          <span style={{display:"inline-flex",alignItems:"center",gap:6,padding:"6px 12px",borderRadius:999,background:"#F1F2F4",color:"#4b5563",fontSize:10,fontWeight:700,...dataFont}}><HeartHandshake size={12}/>{assignedK.length} karyakarta</span>
          <span style={{display:"inline-flex",alignItems:"center",gap:6,padding:"6px 12px",borderRadius:999,background:"#F1F2F4",color:"#4b5563",fontSize:10,fontWeight:700,...dataFont}}><ImageIcon size={12}/>{galleryMedia} media</span>
        </div>

        {desc&&<div style={{marginTop:14}}>
          <div style={{fontSize:11,fontWeight:700,color:"#687386",letterSpacing:".08em",marginBottom:6}}>ABOUT THIS PROJECT</div>
          <div style={{fontSize:12.5,color:"#4b5563",lineHeight:1.6}}>
            {descIsLong&&!descOpen?`${desc.slice(0,150).trim()}… `:`${desc} `}
            {descIsLong&&<button onClick={()=>setDescOpen(o=>!o)} style={{border:0,background:"transparent",color:C.brand,fontWeight:700,fontSize:12.5,cursor:"pointer",padding:0,...sans}}>{descOpen?"Show less":"Read more"}</button>}
          </div>
        </div>}
      </div>
    </div>
    <main style={{padding:"0 0 24px",...sans}}>
    <div className="hide-scroll" style={{padding:"12px 0 10px",display:"flex",gap:8,overflowX:"auto",scrollbarWidth:"none",msOverflowStyle:"none",borderBottom:"1px solid #e5e7eb"}}>
      <button type="button" onClick={()=>setSelectedDate("__all__")} style={{flex:"0 0 auto",border:`1px solid ${isAllProject?C.brand:"#e1e6ec"}`,background:isAllProject?C.brand:"white",color:isAllProject?"white":"#526174",borderRadius:12,padding:"8px 12px",cursor:"pointer",...sans}}><div style={{fontSize:9,fontWeight:700,opacity:.78}}>FULL PROJECT</div><div style={{fontSize:11,fontWeight:700,marginTop:2}}>All days</div></button>
      {projectDates.map(d=><button key={d} type="button" onClick={()=>setSelectedDate(d)} style={{flex:"0 0 auto",border:`1px solid ${selectedDate===d?C.brand:"#e1e6ec"}`,background:selectedDate===d?C.brand:"white",color:selectedDate===d?"white":"#526174",borderRadius:12,padding:"11px 14px",cursor:"pointer",...sans}}><div style={{fontSize:11,fontWeight:700}}>{formatDate(d)}</div></button>)}
    </div>
{visibleTabs.length>1&&<div className="admin-tabs" style={{display:"grid",gridTemplateColumns:`repeat(${visibleTabs.length},minmax(0,1fr))`,width:"100%",borderBottom:"1px solid #e5e7eb",marginBottom:14,boxSizing:"border-box"}}>{visibleTabs.map(t=>{const I=t.i,a=tab===t.k;return <button key={t.k} onClick={()=>setTab(t.k)} style={{width:"100%",minWidth:0,border:0,borderBottom:`2px solid ${a?C.brand:"transparent"}`,background:"transparent",padding:"10px 2px",color:a?C.brand:"#6b7280",fontSize:10,fontWeight:700,cursor:"pointer",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",boxSizing:"border-box",...sans}}><I size={15} strokeWidth={1.5}/><div style={{marginTop:3,whiteSpace:"nowrap"}}>{t.l}</div></button>})}</div>}
    {tab==="photos"&&featureEnabled.photos&&<>{canEdit&&<><input id="baps-photo-upload" ref={photoInputRef} type="file" accept="image/*" onChange={uploadPhoto} disabled={uploading} style={{position:"absolute",width:1,height:1,opacity:0,pointerEvents:"none"}}/><label htmlFor="baps-photo-upload" style={{display:"inline-flex",alignItems:"center",justifyContent:"center",gap:7,borderRadius:6,padding:"9px 13px",fontSize:13,fontWeight:600,cursor:uploading?"not-allowed":"pointer",opacity:uploading?.55:1,background:C.brand,color:"white",border:`1px solid ${C.brand}`,...sans}}>{uploading?<Loader2 size={14} className="animate-spin"/>:<Plus size={14}/>} Add photo</label></>}{photos.length?<div style={{display:"grid",gridTemplateColumns:"repeat(3,minmax(0,1fr))",gap:8,width:"100%"}}>{photos.map(m=><div key={m.id} style={{position:"relative"}}><img src={m.dataUrl} onClick={()=>setLightbox(m)} style={{width:"100%",height:105,objectFit:"cover",borderRadius:5,cursor:"pointer",border:"1px solid #e5e7eb"}}/>{canEdit&&<button type="button" title="Delete photo" onClick={()=>setDeleteMediaTarget(m)} style={{position:"absolute",right:5,top:5,width:28,height:28,border:"1px solid rgba(255,255,255,.7)",borderRadius:6,background:"rgba(17,24,39,.78)",color:"white",display:"grid",placeItems:"center",cursor:"pointer"}}><Trash2 size={14}/></button>}</div>)}</div>:<EmptyState text="No photos yet." icon={ImageIcon}/>}</>}
    {tab==="videos"&&featureEnabled.videos&&<>{canEdit&&<><input id="baps-video-upload" ref={videoInputRef} type="file" accept="video/*" onChange={uploadVideo} disabled={uploading} style={{position:"absolute",width:1,height:1,opacity:0,pointerEvents:"none"}}/><label htmlFor="baps-video-upload" style={{display:"inline-flex",alignItems:"center",justifyContent:"center",gap:7,borderRadius:6,padding:"9px 13px",fontSize:13,fontWeight:600,cursor:uploading?"not-allowed":"pointer",opacity:uploading?.55:1,background:C.brand,color:"white",border:`1px solid ${C.brand}`,...sans}}>{uploading?<Loader2 size={14} className="animate-spin"/>:<Plus size={14}/>} Add video</label></>}{videos.length?videos.map(m=><div key={m.id} style={{position:"relative",border:"1px solid #e5e7eb",borderRadius:6,padding:7,marginBottom:8,background:"white",width:"100%",boxSizing:"border-box"}}><video src={m.dataUrl} controls style={{width:"100%",display:"block"}}/>{canEdit&&<button type="button" title="Delete video" onClick={()=>setDeleteMediaTarget(m)} style={{position:"absolute",right:12,top:12,width:30,height:30,border:"1px solid rgba(255,255,255,.7)",borderRadius:6,background:"rgba(17,24,39,.78)",color:"white",display:"grid",placeItems:"center",cursor:"pointer"}}><Trash2 size={14}/></button>}</div>):<EmptyState text="No videos yet." icon={VideoIcon}/>}</>}
    {tab==="attendance"&&featureEnabled.attendance&&(normalizedRole==="member"?<EmptyState text="Attendance is available only to karyakarta and admins." icon={CalendarCheck}/>:isAllProject?<div style={{display:"grid",gap:10}}>
      <div style={{background:"white",border:"1px solid #eadfdb",borderRadius:10,padding:12}}><div style={{display:"flex",alignItems:"center",gap:7,fontSize:11,fontWeight:700,color:C.brand}}><CalendarCheck size={15}/> FULL PROJECT ATTENDANCE</div><div style={{fontSize:10,color:"#6b7280",marginTop:4}}>Attendance summary for every active project day.</div></div>
      {projectDates.map((d,i)=>{const day=attendance?.[d]||{};const present=assignedMembers.filter(m=>day[m.id]==="present").length;const absent=assignedMembers.filter(m=>day[m.id]==="absent").length;const marked=present+absent;return <button key={d} type="button" onClick={()=>setSelectedDate(d)} style={{width:"100%",border:"1px solid #e5e7eb",borderRadius:10,background:"white",padding:"11px 12px",display:"grid",gridTemplateColumns:"1fr auto",gap:8,textAlign:"left",cursor:"pointer",...sans}}><div><div style={{fontSize:11,fontWeight:700,color:C.brand}}>{formatDate(d)}</div><div style={{fontSize:9,color:"#7a8796",marginTop:3}}>{marked}/{assignedMembers.length} marked</div></div><div style={{display:"flex",gap:5,alignItems:"center"}}><span style={{fontSize:9,fontWeight:700,color:"#166534",background:"#edf8f0",padding:"5px 7px",borderRadius:999}}>{present} present</span><span style={{fontSize:9,fontWeight:700,color:"#991b1b",background:"#fff2f2",padding:"5px 7px",borderRadius:999}}>{absent} absent</span><ChevronRight size={15} color="#9aa7b6"/></div></button>})}
    </div>:<div style={{display:"grid",gap:12}}>
  <div style={{background:"white",border:"1px solid #eadfdb",borderRadius:10,padding:12}}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,flexWrap:"wrap"}}>
      <div style={{display:"flex",alignItems:"center",gap:7,fontSize:11,fontWeight:700,color:C.brand}}><CalendarCheck size={15}/> {formatDate(selectedDate)}</div>
      {assignedMembers.length>0&&<div style={{display:"flex",gap:6,flexWrap:"wrap"}}><Button small variant="secondary" onClick={()=>downloadAttendanceExcel(project,assignedMembers,attendance,selectedDate)}><FileSpreadsheet size={13}/>Excel</Button><Button small variant="secondary" onClick={()=>downloadAttendancePdf(project,assignedMembers,attendance,selectedDate)}><Download size={13}/>PDF</Button></div>}
    </div>
  </div>
  <div style={{background:"white",border:"1px solid #eadfdb",borderRadius:10,padding:12}}>
    <div style={{position:"relative",marginBottom:12}}><Search size={14} style={{position:"absolute",left:11,top:10,color:"#9ca3af"}}/><input value={attendanceSearch} onChange={e=>setAttendanceSearch(e.target.value)} placeholder="Search member ID or name" style={{width:"100%",height:34,border:"1px solid #e5e7eb",borderRadius:7,padding:"0 34px",outline:"none",...dataFont,fontSize:11}}/>{attendanceSearch&&<button type="button" onClick={()=>setAttendanceSearch("")} style={{position:"absolute",right:7,top:6,width:22,height:22,border:0,borderRadius:5,background:"#f3f4f6",color:"#6b7280",cursor:"pointer"}}><X size={13}/></button>}</div>
    {filteredAttendanceMembers.length?<div style={{display:"grid",gridTemplateColumns:"1fr",gap:7}}>{filteredAttendanceMembers.map(m=>{const s=draft[m.id];const present=s==="present";const absent=s==="absent";return <div key={m.id} style={{border:`1px solid ${present?C.brand:absent?"#e5b8b8":"#e5e7eb"}`,borderRadius:9,padding:"8px 10px",background:present?"#fbf7f6":absent?"#fffafa":"white",display:"flex",alignItems:"center",gap:10,width:"100%",boxSizing:"border-box"}}><div style={{minWidth:0,flex:1}}><div style={{fontSize:11,fontWeight:700,...sans,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{m.name}</div><div style={{fontSize:9,color:"#6b7280",marginTop:2,...dataFont}}>{m.id}</div></div><div style={{display:"flex",gap:5,flexShrink:0,marginLeft:"auto"}}><button disabled={!canEdit} title="Present" onClick={()=>setDraft(d=>({...d,[m.id]:"present"}))} style={{width:34,height:30,border:`1px solid ${present?C.brand:"#dfe3e8"}`,background:present?C.brand:"white",color:present?"white":"#6b7280",borderRadius:6,display:"grid",placeItems:"center",cursor:canEdit?"pointer":"not-allowed"}}><Check size={13}/></button><button disabled={!canEdit} title="Absent" onClick={()=>setDraft(d=>({...d,[m.id]:"absent"}))} style={{width:34,height:30,border:`1px solid ${absent?"#991b1b":"#dfe3e8"}`,background:absent?"#991b1b":"white",color:absent?"white":"#6b7280",borderRadius:6,display:"grid",placeItems:"center",cursor:canEdit?"pointer":"not-allowed"}}><X size={13}/></button></div></div>})}</div>:<EmptyState text={attendanceSearch.trim()?"No matching haribhakto found.":"No haribhakto assigned to this project."} icon={CalendarCheck}/>}</div>
  {canEdit&&assignedMembers.length>0&&<div style={{display:"flex",justifyContent:"flex-end"}}><Button onClick={saveAttendance}><Save size={14}/>Save attendance</Button></div>}
 </div>)}{tab==="forms"&&featureEnabled.forms&&<FormsPanel project={project} currentUser={currentUser} members={members} selectedDate={selectedDate}/>}  </main>{lightbox&&<div onClick={()=>setLightbox(null)} style={{position:"fixed",inset:0,zIndex:50,background:"rgba(0,0,0,.82)",display:"grid",placeItems:"center",padding:18}}><img src={lightbox.dataUrl} style={{maxWidth:"100%",maxHeight:"88vh",objectFit:"contain"}}/></div>}<ConfirmDialog open={!!deleteMediaTarget} title={`Delete ${deleteMediaTarget?.type==="photo"?"photo":"video"}?`} message={`This will permanently delete this ${deleteMediaTarget?.type==="photo"?"photo":"video"} from the project.`} confirmText="Delete" onCancel={()=>!deleteMediaBusy&&setDeleteMediaTarget(null)} onConfirm={deleteMedia} busy={deleteMediaBusy}/></div>;
}

function ProfileScreen({currentUser,onLogout}){
  return <main style={{padding:20,...sans}}>
    <div style={{fontSize:19,fontWeight:700,color:C.brand,marginBottom:16}}>Profile</div>
    <div className="baps-card profile-card" style={{background:"white",overflow:"visible",position:"relative",width:"100%",boxSizing:"border-box"}}>
      <div style={{height:"clamp(180px,28vw,230px)",minHeight:180,maxHeight:230,width:"100%",position:"relative",overflow:"hidden",borderRadius:"28px 28px 0 0",background:"#eaf2fa"}}>
        <SafeImage src={PROFILE_HERO} alt="BAPS Swaminarayan Mandir" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>
        <div style={{position:"absolute",inset:0,background:"linear-gradient(180deg,rgba(10,45,82,0) 48%,rgba(10,45,82,.28) 100%)"}}/>
      </div>
      <div className="profile-details" style={{padding:"0 20px 22px",position:"relative",boxSizing:"border-box"}}>
        <div style={{display:"flex",justifyContent:"center",marginTop:-58}}>
          <div style={{width:116,height:116,borderRadius:"50%",background:"white",padding:6,boxShadow:"0 12px 30px rgba(24,39,58,.18)",position:"relative",zIndex:2}}>
            {currentUser.photo
              ? <img src={currentUser.photo} alt={`${currentUser.name} profile`} style={{width:"100%",height:"100%",objectFit:"cover",borderRadius:"50%",display:"block"}}/>
              : <SafeImage src={APP_LOGO} alt="BAPS Rajkot" style={{width:"100%",height:"100%",objectFit:"cover",borderRadius:"50%",display:"block"}}/>}
          </div>
        </div>
        <div style={{textAlign:"center",marginTop:12}}>
          <div style={{fontSize:"clamp(20px,4vw,28px)",fontWeight:700,color:"#101827",letterSpacing:"-.04em"}}>{currentUser.name}</div>
          <div style={{fontSize:11,color:"#687386",marginTop:5,...dataFont}}>{currentUser.id}</div>
          <div style={{display:"flex",justifyContent:"center",gap:7,flexWrap:"wrap",marginTop:12}}><RoleBadge role={currentUser.role}/>{currentUser.mandal&&<span style={{display:"inline-flex",alignItems:"center",gap:5,padding:"5px 10px",borderRadius:999,background:"#F1F2F4",color:"#4b5563",fontSize:10,fontWeight:700}}><MapPin size={11}/>{currentUser.mandal}</span>}</div>
        </div>
        <div style={{marginTop:22,border:"1px solid #e5e8ec",borderRadius:18,overflow:"hidden",background:"#fff"}}>
          {[
            ["Haribhakto ID",currentUser.id,ClipboardList],
            ["Name",currentUser.name,UserIcon],
            ["Mandal",currentUser.mandal||"—",MapPin],
            ["Ksetra",currentUser.ksetra||"—",MapPin],
            ["Role",String(currentUser.role||"member").replace(/^./,x=>x.toUpperCase()),Shield]
          ].map(([label,value,Icon],i)=><div key={label} style={{display:"flex",alignItems:"center",gap:11,padding:"13px 14px",borderBottom:i<4?"1px solid #f0f2f5":"none"}}>
            <div style={{width:32,height:32,borderRadius:10,background:"var(--ui-blue-soft)",color:C.brand,display:"grid",placeItems:"center",flexShrink:0}}><Icon size={15} strokeWidth={1.7}/></div>
            <div style={{minWidth:0,flex:1}}><div style={{fontSize:9,color:"#9aa3af",fontWeight:700,letterSpacing:".10em",textTransform:"uppercase"}}>{label}</div><div style={{fontSize:12,fontWeight:600,color:"#273142",marginTop:3,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",...dataFont}}>{value}</div></div>
          </div>)}
        </div>
        <div style={{marginTop:16,padding:16,borderRadius:18,background:"#f7f9fb",border:"1px solid #edf0f3"}}>
          <div style={{display:"flex",alignItems:"center",gap:8,fontSize:12,fontWeight:700,color:"#101827"}}><HeartHandshake size={16} color={C.brand}/>BAPS Rajkot</div>
          <div style={{fontSize:11,color:"#687386",lineHeight:1.6,marginTop:7}}>Seva · Satsang · Ekta</div>
        </div>
        <div style={{display:"flex",justifyContent:"center",marginTop:18}}><Button variant="secondary" onClick={onLogout}><LogOut size={14}/>Sign out</Button></div>
      </div>
    </div>
  </main>
}

function MemberForm({initial,onCancel,onSave}){
  const[f,setF]=useState({id:initial?.id||"",name:initial?.name||"",mandal:initial?.mandal||"",ksetra:initial?.ksetra||"",role:initial?.role||"member",password:initial?.password||"",tags:Array.isArray(initial?.tags)?initial.tags:[],photo:initial?.photo||""});
  const[photoFile,setPhotoFile]=useState(null);const[photoPreview,setPhotoPreview]=useState(initial?.photo||"");const[busy,setBusy]=useState(false);
  const choosePhoto=e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith("image/")){appToast("Please select an image file.","error");return}if(file.size>8*1024*1024){appToast("Profile photo must be smaller than 8 MB.","error");return}setPhotoFile(file);const rd=new FileReader();rd.onload=ev=>setPhotoPreview(String(ev.target.result||""));rd.readAsDataURL(file)};
  const submit=async()=>{if(!f.id.trim()||!f.name.trim()){appToast("Haribhakto ID and Name are required.","error");return}if(!f.password){appToast("Password is required.","error");return}if(String(f.role||"member").toLowerCase()!=="admin"&&!photoPreview){appToast("Profile photo is required for haribhakto and karyakartas.","error");return}setBusy(true);try{await onSave({...f,photoFile,photo:photoPreview})}finally{setBusy(false)}};
  const inputId=`profile-photo-${initial?.id||"new"}`;
  return <div className="baps-card" style={{background:"white",border:"1px solid #e5e7eb",borderRadius:18,padding:16,marginBottom:14}}>
    <div style={{fontSize:13,fontWeight:700,marginBottom:14}}>{initial?"Edit haribhakto":"Add haribhakto"}</div>
    <div style={{display:"flex",alignItems:"center",gap:14,padding:12,borderRadius:16,background:"#f7f9fb",border:"1px solid #e8edf2",marginBottom:16}}>
      <div style={{width:76,height:76,borderRadius:"50%",overflow:"hidden",background:"#edf3f8",border:"2px solid white",boxShadow:"0 5px 15px rgba(24,39,58,.10)",display:"grid",placeItems:"center",flexShrink:0}}>
        {photoPreview?<img src={photoPreview} alt="Profile preview" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>:<UserIcon size={28} color="#9aa7b6"/>}
      </div>
      <div style={{minWidth:0,flex:1}}>
        <div style={{fontSize:11,fontWeight:700,color:"#172033",marginBottom:4}}>Profile photo {String(f.role||"member").toLowerCase()==="admin"?<span style={{color:"#7b8795",fontWeight:500}}>(optional)</span>:<span style={{color:"#991b1b"}}>*</span>}</div>
        <div style={{fontSize:10,color:"#7b8795",lineHeight:1.45,marginBottom:8}}>{String(f.role||"member").toLowerCase()==="admin"?"Optional for admin. If added, it will be shown on the profile.":"Required for login and shown on the profile."}</div>
        <input id={inputId} type="file" accept="image/*" onChange={choosePhoto} style={{display:"none"}}/>
        <label htmlFor={inputId} style={{display:"inline-flex",alignItems:"center",gap:6,padding:"8px 11px",borderRadius:10,background:C.brand,color:"white",fontSize:10,fontWeight:700,cursor:"pointer",...sans}}><ImageIcon size={13}/>{photoPreview?"Change photo":"Choose photo"}</label>
      </div>
    </div>
    <Field label="Haribhakto ID" value={f.id} disabled={!!initial} onChange={e=>setF({...f,id:e.target.value.toUpperCase()})}/>
    <Field label="Name" value={f.name} onChange={e=>setF({...f,name:e.target.value})}/>
    <Field label="Mandal" value={f.mandal} onChange={e=>setF({...f,mandal:e.target.value})}/>
    <Field label="Ksetra" value={f.ksetra} onChange={e=>setF({...f,ksetra:e.target.value})}/>
    <SelectField label="Role" value={f.role} onChange={e=>setF({...f,role:e.target.value})} options={[{value:"member",label:"Haribhakto"},{value:"karyakarta",label:"Karyakarta"},{value:"admin",label:"Admin"}]}/>
    <Field label="Password" type="password" value={f.password} onChange={e=>setF({...f,password:e.target.value})} clearable={false}/>
    <TagPicker label="MEMBER TAGS" value={f.tags} onChange={tags=>setF({...f,tags})}/>
    <div style={{display:"flex",gap:8,flexWrap:"wrap"}}><Button onClick={submit} disabled={busy}>{busy?<Loader2 size={14} className="animate-spin"/>:<Save size={14}/>} {initial?"Save changes":"Add haribhakto"}</Button><Button variant="secondary" onClick={onCancel} disabled={busy}>Cancel</Button></div>
  </div>;
}

function MemberDetailsModal({member,projects,onClose,onEdit,onDelete}){
  if(!member)return null;
  const memberPhoto=member.photo||"";
  const memberProjects=(projects||[]).filter(p=>(p.assignedMembers||[]).includes(member.id));
  const karyakartaProjects=(projects||[]).filter(p=>(p.assignedKaryakarta||[]).includes(member.id));
  const allProjects=[...new Map([...memberProjects,...karyakartaProjects].map(p=>[String(p.id),p])).values()];
  return <Modal open={!!member} title="Haribhakto details" description="Complete haribhakto information." onClose={onClose} wide>
    <div style={{display:"grid",gap:14}}>
      <div style={{display:"flex",alignItems:"center",gap:14,padding:14,borderRadius:18,background:"#f7f9fb",border:"1px solid #e8edf2"}}>
        <div style={{width:82,height:82,borderRadius:"50%",overflow:"hidden",background:"#edf3f8",border:"2px solid white",boxShadow:"0 6px 18px rgba(24,39,58,.10)",display:"grid",placeItems:"center",flexShrink:0}}>
          {memberPhoto ? (
            <img src={memberPhoto} alt="" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}} />
          ) : (
            <UserIcon size={30} color={C.brand} />
          )}
        </div>
        <div style={{minWidth:0}}>
          <div style={{fontSize:18,fontWeight:700,color:"#101827",...sans}}>{member.name}</div>
          <div style={{fontSize:11,color:"#687386",marginTop:4,...dataFont}}>{member.id}</div>
          <div style={{marginTop:8}}><RoleBadge role={member.role}/></div>
        </div>
      </div>
      <div style={{border:"1px solid #e5e8ec",borderRadius:16,overflow:"hidden",background:"white"}}>
        {[["Haribhakto ID",member.id,ClipboardList],["Name",member.name,UserIcon],["Mandal",member.mandal||"—",MapPin],["Ksetra",member.ksetra||"—",MapPin],["Role",String(member.role||"member").replace(/^./,x=>x.toUpperCase()),Shield],["Password","••••••••",Lock]].map(([label,value,Icon],i)=><div key={label} style={{display:"flex",alignItems:"center",gap:11,padding:"12px 14px",borderBottom:i<5?"1px solid #f0f2f5":"none"}}><div style={{width:32,height:32,borderRadius:10,background:"var(--ui-blue-soft)",color:C.brand,display:"grid",placeItems:"center",flexShrink:0}}><Icon size={15} strokeWidth={1.7}/></div><div style={{minWidth:0,flex:1}}><div style={{fontSize:9,color:"#9aa3af",fontWeight:700,letterSpacing:".10em",textTransform:"uppercase"}}>{label}</div><div style={{fontSize:12,fontWeight:600,color:"#273142",marginTop:3,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",...dataFont}}>{value}</div></div></div>)}
      </div>
      <div style={{border:"1px solid #e5e8ec",borderRadius:16,padding:14,background:"#fff"}}>
        <div style={{fontSize:11,fontWeight:700,color:"#101827",marginBottom:9}}>Assigned projects</div>
        {allProjects.length?<div style={{display:"grid",gap:7}}>{allProjects.map(p=><div key={p.id} style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,padding:"9px 10px",borderRadius:10,background:"#f7f9fb",border:"1px solid #edf0f3"}}><div style={{minWidth:0,flex:1}}><div style={{fontSize:11,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{p.name}</div><div style={{fontSize:9,color:"#7a8796",marginTop:2}}>{memberProjects.some(x=>String(x.id)===String(p.id))?"Member":"Karyakarta"}</div></div><FolderOpen size={14} color={C.brand}/></div>)}</div>:<div style={{fontSize:10,color:"#9aa3af"}}>No projects assigned.</div>}
      </div>
      {member.tags?.length>0&&<div style={{border:"1px solid #e5e8ec",borderRadius:16,padding:14,background:"#fff"}}><div style={{fontSize:11,fontWeight:700,color:"#101827",marginBottom:8}}>Tags</div><div style={{display:"flex",gap:6,flexWrap:"wrap"}}>{member.tags.map((t,i)=><span key={`${t}-${i}`} style={{padding:"5px 9px",borderRadius:999,background:"#f1f4f7",color:"#536174",fontSize:9,fontWeight:700}}>{t}</span>)}</div></div>}
      <div style={{display:"flex",gap:8,justifyContent:"flex-end",flexWrap:"wrap"}}><Button variant="secondary" onClick={()=>onEdit(member)}><Pencil size={14}/>Edit haribhakto</Button><Button variant="secondary" onClick={()=>onDelete(member)}><Trash2 size={14}/>Delete haribhakto</Button></div>
    </div>
  </Modal>;
}

function AdminScreen({members,projects,events=[],refreshMembers,refreshProjects,refreshEvents,onCreateProject,currentUser}){
  const [tab,setTab]=useState("members");
  const [memberSearch,setMemberSearch]=useState("");
  const [editingMember,setEditingMember]=useState(null);
  const [selectedMember,setSelectedMember]=useState(null);
  const [adding,setAdding]=useState(false);
  const [editingProject,setEditingProject]=useState(null);
  const [newProjectOpen,setNewProjectOpen]=useState(false);
  const [editingEvent,setEditingEvent]=useState(null);
  const [newEventOpen,setNewEventOpen]=useState(false);
  const [deleteTarget,setDeleteTarget]=useState(null);
  const [deleteBusy,setDeleteBusy]=useState(false);
  const [notificationSending,setNotificationSending]=useState(false);

  const sendNotification=async({title,message,audience,projectId})=>{
    setNotificationSending(true);
    try{
      const created=await sb("notifications",{
        method:"POST",
        headers:{Prefer:"return=representation"},
        body:JSON.stringify([{
          title,
          message,
          audience:audience||"all",
          project_id:projectId||null,
          created_by:currentUser?.id||""
        }])
      });

      const notificationId=created?.[0]?.id;
      if(!notificationId) throw new Error("Notification row was created without an ID.");

      const sendPush=async id=>{
        const pushRes=await fetch(`${SUPABASE_URL}/functions/v1/send-notification`,{
          method:"POST",
          headers:{apikey:SUPABASE_ANON_KEY,"Content-Type":"application/json"},
          body:JSON.stringify({notification_id:id})
        });
        const pushText=await pushRes.text();
        let pushData={};try{pushData=JSON.parse(pushText||"{}")}catch{}
        if(!pushRes.ok)throw new Error(pushData?.error||`Push server returned HTTP ${pushRes.status}`);
        return pushData;
      };

      let pushData=await sendPush(notificationId);

      // Project push fallback: create one member-targeted notification per assigned member.
      // This avoids relying on the Edge Function to resolve project haribhaktohip itself.
      if(audience==="project" && Number(pushData?.attempted||0)===0 && projectId){
        const project=projects.find(p=>String(p.id)===String(projectId));
        const memberIds=Array.isArray(project?.assignedMembers)?project.assignedMembers.map(String).filter(Boolean):[];
        if(memberIds.length){
          const targeted=await sb("notifications",{
            method:"POST",
            headers:{Prefer:"return=representation"},
            body:JSON.stringify(memberIds.map(member_id=>({title,message,audience:"member",project_id:projectId,member_id,created_by:currentUser?.id||""})))
          });
          const targetedRows=Array.isArray(targeted)?targeted:[];
          const results=[];
          for(const row of targetedRows){
            try{results.push(await sendPush(row.id))}catch(err){results.push({attempted:0,error:err?.message||String(err)})}
          }
          const attempted=results.reduce((n,x)=>n+Number(x?.attempted||0),0);
          const failed=results.reduce((n,x)=>n+(Array.isArray(x?.results)?x.results.filter(v=>!v?.ok).length:0),0);
          if(attempted>0){
            appToast(failed?`Project notification sent. ${failed} device(s) could not receive push.`:"Notification sent to project.","success");
            return;
          }
        }
      }

      if(Number(pushData?.attempted||0)===0){
        if(audience==="project" && projectId){
          const eligible=Number(pushData?.eligible_members||0);
          const subscribed=Number(pushData?.subscribed_members||0);
          throw new Error(`No registered push devices for this project. ${eligible} assigned people found, ${subscribed} have push enabled. Each receiving device must enable app notifications once.`);
        }
        throw new Error("No registered push devices. Each receiving device must enable app notifications once.");
      }
      const failed=(Array.isArray(pushData?.results)?pushData.results:[]).filter(x=>!x?.ok).length;
      if(failed)appToast(`Notification saved. ${failed} device(s) could not receive push.`,"info");
      else appToast(audience==="project"?"Notification sent to project.":"Notification sent to all haribhakto.","success");
    }catch(e){
      console.error("Send notification error:",e);
      appToast(`Could not send notification. ${e?.message||"Unknown error"}`,"error");
      throw e;
    }finally{setNotificationSending(false)}
  };

  const filtered=members.filter(m=>`${m.id} ${m.name} ${m.mandal} ${m.ksetra} ${m.role}`.toLowerCase().includes(memberSearch.toLowerCase()));

  const saveMember=async f=>{
    try{
      let photo=f.photo||editingMember?.photo||"";
      if(f.photoFile){
        const compressed=await compressImage(f.photoFile,900,.78);
        try{
          const blob=await (await fetch(compressed)).blob();
          photo=await uploadToBucket(blob,`profiles/${encodeURIComponent(f.id.trim().toUpperCase())}/${uid("avatar")}.jpg`);
        }catch(storageErr){
          if(compressed.length>6500000)throw storageErr;
          photo=compressed;
          appToast("Storage upload failed; saving the compressed profile photo directly.","info");
        }
      }
      // Profile photo is required only for haribhakto and karyakartas. Admin can be saved without a photo.
      const roleForSave=String(f.role||"member").toLowerCase();
      if(roleForSave!=="admin"&&!photo)throw new Error("Profile photo is required.");
      const tags=Array.isArray(f.tags)?f.tags.filter(t=>!(typeof t==="string"&&t.startsWith(PROFILE_PHOTO_PREFIX))):[];
      const photoTag=memberPhotoTag(photo);if(photoTag)tags.push(photoTag);
      const payload={ID:f.id.trim().toUpperCase(),Name:f.name.trim(),Mandal:f.mandal.trim(),Ksetra:f.ksetra.trim(),Role:f.role||"member",Password:f.password,Tags:tags};
      if(!payload.ID||!payload.Name)throw new Error("Haribhakto ID and Name are required.");
      if(!payload.Password)throw new Error("Password is required.");
      if(editingMember)await sb(`members?ID=eq.${encodeURIComponent(editingMember.id)}`,{method:"PATCH",body:JSON.stringify(payload)});
      else await sb("members",{method:"POST",body:JSON.stringify([payload])});
      setEditingMember(null);setAdding(false);await refreshMembers();appToast("Haribhakto saved.","success");
    }catch(e){console.error("Save member error:",e);appToast(`Could not save member. ${e?.message||"Unknown database error"}`,"error");throw e}
  };

  const delMember=async()=>{
    const m=deleteTarget;if(!m)return;setDeleteBusy(true);
    try{
      await sb(`members?ID=eq.${encodeURIComponent(m.id)}`,{method:"DELETE"});
      setDeleteTarget(null);await refreshMembers();appToast("Haribhakto deleted.","success");
    }catch(e){
      appToast(`Could not delete member. ${e?.message||"Unknown database error"}`,"error");
    }finally{setDeleteBusy(false)}
  };

  const delProject=async()=>{
    const p=deleteTarget;if(!p)return;setDeleteBusy(true);
    try{
      await sb(`projects?id=eq.${p.id}`,{method:"DELETE"});
      setDeleteTarget(null);await refreshProjects();appToast("Project deleted.","success");
    }catch(e){
      appToast(`Could not delete project. ${e?.message||"Unknown database error"}`,"error");
    }finally{setDeleteBusy(false)}
  };

  const createAdminEvent=async d=>{try{await sb("events",{method:"POST",body:JSON.stringify([{name:d.name,description:d.description,start_date:d.startDate,end_date:d.endDate,created_by:currentUser?.id||""}])});appToast("Event created.","success");setNewEventOpen(false);await refreshEvents?.();}catch(e){appToast(`Could not create event. ${e?.message||"Unknown database error"}`,"error");throw e}};
  const updateAdminEvent=async(ev,d)=>{try{await sb(`events?id=eq.${encodeURIComponent(ev.id)}`,{method:"PATCH",body:JSON.stringify({name:d.name,description:d.description,start_date:d.startDate,end_date:d.endDate})});appToast("Event updated.","success");setEditingEvent(null);await refreshEvents?.();}catch(e){appToast(`Could not update event. ${e?.message||"Unknown database error"}`,"error");throw e}};
  const deleteAdminEvent=async ev=>{if(!window.confirm(`Delete event “${ev.name}”? Projects inside it will remain, but will no longer belong to this event.`))return;try{await sb(`events?id=eq.${encodeURIComponent(ev.id)}`,{method:"DELETE"});appToast("Event deleted.","success");await refreshEvents?.();}catch(e){appToast(`Could not delete event. ${e?.message||"Unknown database error"}`,"error")}};
  const deleteIsProject=deleteTarget?.kind==="project";

  return <div>
    <TopBar title="Admin" subtitle="Haribhakto, roles, events and projects" currentUser={currentUser}/>
    <main style={{padding:16,...sans}}>
      <div style={{display:"flex",borderBottom:"1px solid #e5e7eb",marginBottom:14}}>
        {[['members','Haribhakto'],['events','Events'],['projects','Projects'],['notifications','Notifications']].map(([k,l])=><button key={k} onClick={()=>setTab(k)} style={{border:0,borderBottom:`2px solid ${tab===k?C.brand:"transparent"}`,background:"transparent",padding:"9px 12px",fontSize:11,fontWeight:700,color:tab===k?C.brand:"#6b7280",cursor:"pointer",...sans}}>{l}</button>)}
      </div>

      <MemberDetailsModal member={selectedMember} projects={projects} onClose={()=>setSelectedMember(null)} onEdit={m=>{setSelectedMember(null);setEditingMember(m);setAdding(false)}} onDelete={m=>{setSelectedMember(null);setDeleteTarget({kind:"member",...m})}}/>

      <Modal open={adding} title="Add haribhakto" description="Create a haribhakto account." onClose={()=>setAdding(false)}>
        <MemberForm onCancel={()=>setAdding(false)} onSave={saveMember}/>
      </Modal>

      <Modal open={!!editingMember} title="Edit haribhakto" description="Update haribhakto details and role." onClose={()=>setEditingMember(null)}>
        <MemberForm initial={editingMember} onCancel={()=>setEditingMember(null)} onSave={saveMember}/>
      </Modal>

      <Modal open={!!editingProject} title="Edit project" description="Update project details, haribhakto and project karyakartas." onClose={()=>setEditingProject(null)} wide>
        <ProjectForm
          initial={editingProject}
          members={members}
          events={events}
          onCancel={()=>setEditingProject(null)}
          onSave={async d=>{
            try{
              await sb(`projects?id=eq.${encodeURIComponent(editingProject.id)}`,{method:"PATCH",body:JSON.stringify({
                name:d.name,category:d.category,description:d.description,event_id:d.eventId||null,project_date:d.projectStartDate,
                project_start_date:d.projectStartDate,project_end_date:d.projectEndDate,project_dates:d.projectDates,
                enable_photos:d.enablePhotos,enable_videos:d.enableVideos,enable_attendance:d.enableAttendance,enable_forms:d.enableForms,
                cover_photo:d.coverPhoto||null,assigned_members:d.assignedMembers,assigned_karyakarta:d.assignedKaryakarta
              })});
              if(d.coverPhoto&&d.coverFile){
                let cover=d.coverPhoto;
                try{const compressed=await compressImage(d.coverFile,1400,.80);try{const blob=await (await fetch(compressed)).blob();cover=await uploadToBucket(blob,`projects/${encodeURIComponent(String(editingProject.id))}/${uid("cover")}.jpg`)}catch{cover=compressed}}catch{}
                await sb(`projects?id=eq.${encodeURIComponent(editingProject.id)}`,{method:"PATCH",body:JSON.stringify({cover_photo:cover})});
              }
              setEditingProject(null);await refreshProjects();appToast("Project updated.","success");
            }catch(e){appToast(`Could not update project. ${e?.message||"Unknown database error"}`,"error");throw e}
          }}
        />
      </Modal>

      <Modal open={newProjectOpen} title="New project" description="Create a seva project, select haribhakto and assign project karyakartas." onClose={()=>setNewProjectOpen(false)} wide>
        <ProjectForm members={members} events={events} onCancel={()=>setNewProjectOpen(false)} onSave={async d=>{await onCreateProject(d);setNewProjectOpen(false)}}/>
      </Modal>

      <ConfirmDialog
        open={!!deleteTarget}
        title={deleteIsProject?"Delete project?":"Delete member?"}
        message={deleteIsProject?`This will permanently delete “${deleteTarget?.name||""}”.`:`This will permanently delete haribhakto ${deleteTarget?.id||""}.`}
        onCancel={()=>!deleteBusy&&setDeleteTarget(null)}
        onConfirm={deleteIsProject?delProject:delMember}
        busy={deleteBusy}
      />

      {tab==="members"&&<>
        <div className="search-row" style={{marginBottom:10}}>
          <div className="search-field-wrap">
            <Search className="search-icon" size={15} color="#9aa3af"/>
            <input value={memberSearch} onChange={e=>setMemberSearch(e.target.value)} placeholder="Search ID, name, Mandal, Ksetra or role" className={`app-input search-input${memberSearch?" has-value":""}`}/>
            {memberSearch&&<button type="button" aria-label="Clear search" className="search-clear" onClick={()=>setMemberSearch("")} style={{width:28,height:28,border:0,borderRadius:8,background:"#f3f4f6",color:"#6b7280",display:"grid",placeItems:"center",cursor:"pointer"}}><X size={14}/></button>}
          </div>
          <Button small onClick={()=>{setAdding(true);setEditingMember(null)}}><UserPlus size={14}/>Add haribhakto</Button>
        </div>
        <div className="baps-card" style={{background:"white",border:"1px solid #e5e7eb",borderRadius:6,overflow:"hidden"}}>
          {filtered.map(m=><button key={m.id} type="button" className="row member-row" onClick={()=>setSelectedMember(m)} style={{width:"100%",padding:"14px 12px",border:0,borderBottom:"1px solid #f3f4f6",display:"grid",gridTemplateColumns:"44px minmax(0,1fr) 24px",alignItems:"center",columnGap:12,background:"white",cursor:"pointer",textAlign:"left",...sans}}>
            <div style={{width:44,height:44,borderRadius:"50%",overflow:"hidden",background:"#eef3f8",border:"1px solid #e0e7ef",display:"grid",placeItems:"center",flexShrink:0}}>{m.photo?<img src={m.photo} alt="" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>:<UserIcon size={19} color={C.brand}/>}</div>
            <div style={{minWidth:0,flex:1}}><div style={{fontSize:12,fontWeight:700,color:"#101827",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{m.name}</div><div style={{fontSize:10,color:"#687386",marginTop:4,...dataFont}}>{m.id}</div></div>
            <ChevronRight size={17} color="#9aa7b6" style={{justifySelf:"end"}}/>
          </button>)}
          {filtered.length===0&&<EmptyState text="No matching haribhakto." icon={UserIcon}/>} 
        </div>
      </>}

      {tab==="events"&&<>
        <div style={{display:"flex",justifyContent:"flex-end",marginBottom:10}}><Button small onClick={()=>setNewEventOpen(true)}><Plus size={14}/>New event</Button></div>
        <div className="baps-card" style={{background:"white",border:"1px solid #e5e7eb",borderRadius:6,overflow:"hidden"}}>
          {events.map(ev=>{const ps=projects.filter(p=>p.eventId===ev.id);return <div key={ev.id} className="row" style={{padding:"12px",borderBottom:"1px solid #f3f4f6"}}>
            <div style={{display:"flex",alignItems:"center",gap:9}}>
              <div style={{width:36,height:36,borderRadius:9,background:"var(--ui-blue-soft)",color:C.brand,display:"grid",placeItems:"center",flexShrink:0}}><CalendarDays size={17}/></div>
              <div style={{minWidth:0,flex:1}}>
                <div style={{fontSize:13,fontWeight:700}}>{ev.name}</div>
                <div style={{fontSize:10,color:"#6b7280",marginTop:3}}>{ps.length} {ps.length===1?"project":"projects"} · {formatDate(ev.startDate)}{ev.startDate!==ev.endDate?` – ${formatDate(ev.endDate)}`:""}</div>
              </div>
              <IconButton title="Edit event" onClick={()=>setEditingEvent(ev)}><Pencil size={14}/></IconButton>
              <IconButton title="Delete event" danger onClick={()=>deleteAdminEvent(ev)}><Trash2 size={14}/></IconButton>
            </div>
          </div>})}
          {events.length===0&&<EmptyState text="No events yet." icon={CalendarDays}/>}
        </div>
        <Modal open={newEventOpen} title="New event" description="Create an event and place seva projects inside it." onClose={()=>setNewEventOpen(false)}><EventForm onCancel={()=>setNewEventOpen(false)} onSave={createAdminEvent}/></Modal>
        <Modal open={!!editingEvent} title="Edit event" description="Update event details." onClose={()=>setEditingEvent(null)}><EventForm initial={editingEvent} onCancel={()=>setEditingEvent(null)} onSave={async d=>updateAdminEvent(editingEvent,d)}/></Modal>
      </>}

      {tab==="projects"&&<>
        <div style={{display:"flex",justifyContent:"flex-end",marginBottom:10}}><Button small onClick={()=>setNewProjectOpen(true)}><Plus size={14}/>New project</Button></div>
        <div className="baps-card" style={{background:"white",border:"1px solid #e5e7eb",borderRadius:6,overflow:"hidden"}}>
          {projects.slice().sort((a,b)=>String(a.projectStartDate||a.projectDate||"").localeCompare(String(b.projectStartDate||b.projectDate||""))||String(a.name||"").localeCompare(String(b.name||""))).map(p=><div key={p.id} className="row" style={{padding:"12px",borderBottom:"1px solid #f3f4f6"}}><div style={{display:"flex",alignItems:"center",gap:8}}><div style={{minWidth:0,flex:1}}><div style={{fontSize:13,fontWeight:600,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{p.name}</div><div style={{fontSize:10,color:"#6b7280",marginTop:3,...dataFont}}>{(p.assignedMembers||[]).length} members · {(p.assignedKaryakarta||[]).length} karyakarta · {events.find(e=>e.id===p.eventId)?.name?`${events.find(e=>e.id===p.eventId).name} · `:""}{p.projectStartDate===p.projectEndDate?formatDate(p.projectStartDate):`${formatDate(p.projectStartDate)} – ${formatDate(p.projectEndDate)}`}</div></div><IconButton title="Edit project" onClick={()=>setEditingProject(p)}><Pencil size={14} strokeWidth={1.5}/></IconButton><IconButton title="Delete project" danger onClick={()=>setDeleteTarget({kind:"project",...p})}><Trash2 size={14}/></IconButton></div></div>)}
          {projects.length===0&&<EmptyState text="No projects yet." icon={FolderOpen}/>} 
        </div>
      </>}
      {tab==="notifications"&&<div style={{width:"100%"}}><NotificationComposer onSend={sendNotification} projects={projects}/><div style={{fontSize:9,color:"#9aa3af",marginTop:10,lineHeight:1.5}}>Notifications are stored in Supabase and delivered in real time to logged-in users. App notifications require permission on each device.</div></div>}
    </main>
  </div>;
}

export default function App(){useBrandFonts();useGlobalStyles();useAppBranding();const[loading,setLoading]=useState(true);const[error,setError]=useState("");const[currentUser,setCurrentUser]=useState(()=>{try{const raw=localStorage.getItem(SESSION_KEY);return raw?JSON.parse(raw):null}catch{return null}});const[view,setViewRaw]=useState("home");const[activeProjectId,setActiveProjectId]=useState(null);const[members,setMembers]=useState([]);const[projects,setProjects]=useState([]);const[events,setEvents]=useState([]);const[projectEdit,setProjectEdit]=useState(null);
  const setView=(v,id)=>{setViewRaw(v);if(id)setActiveProjectId(id)};
  const loadMembers=useCallback(async()=>{const r=await sb("members?select=*&order=Name.asc");setMembers((r||[]).map(mapMemberRow))},[]);
  const loadEvents=useCallback(async()=>{try{const r=await sb("events?select=*&order=start_date.asc,created_at.desc");setEvents((r||[]).map(mapEventRow))}catch(e){console.error("Events load error",e);setEvents([])}},[]);
  const loadProjects=useCallback(async()=>{
    const r=await sb("projects?select=*&order=project_start_date.asc,created_at.desc");
    const mapped=(r||[]).map(mapProjectRow);
    try{
      const covers=await sb("project_media?select=project_id,data_url,uploaded_at&type=eq.photo&order=uploaded_at.asc");
      const firstPhoto=new Map();
      (covers||[]).forEach(x=>{const id=String(x.project_id);if(!firstPhoto.has(id)&&x.data_url)firstPhoto.set(id,String(x.data_url))});
      setProjects(mapped.map(p=>({...p,coverPhoto:p.coverPhoto||firstPhoto.get(String(p.id))||""})));
    }catch(e){console.warn("Project photo media could not be loaded:",e);setProjects(mapped);}
  },[]);
  useEffect(()=>{(async()=>{try{await Promise.all([loadMembers(),loadProjects(),loadEvents()])}catch(e){console.error(e);setError("Supabase connection error. Check members/projects tables and RLS.")}finally{setLoading(false)}})()},[loadMembers,loadProjects]);
  useEffect(()=>{if(!currentUser)return;return subscribeRealtime(`app-${currentUser.id}`,{"projects":()=>loadProjects(),"members":()=>loadMembers(),"events":()=>loadEvents()})},[currentUser,loadMembers,loadProjects]);
  const login=async(rawId,password)=>{try{const id=rawId.trim().toUpperCase();const r=await sb(`members?ID=eq.${encodeURIComponent(id)}&select=*`);const m=r?.[0];if(!m)return "Member ID not found.";const storedPassword=String(m.Password??m.password??m.PASSWORD??m.password_hash??"");const enteredPassword=String(password??"");if(storedPassword!==enteredPassword)return "Incorrect password.";const rawTags=Array.isArray(m.Tags)?m.Tags:(Array.isArray(m.tags)?m.tags:[]);const role=String(m.Role??m.role??"member").toLowerCase();const photo=extractMemberPhoto(rawTags,m.Photo??m.photo??m.profile_photo??"");if(role!=="admin"&&!photo)return "This account has no profile photo. Ask the admin to add one before signing in.";const user={id:String(m.ID??m.id),username:String(m.ID??m.id),name:String(m.Name??m.name??""),mandal:String(m.Mandal??m.mandal??""),ksetra:String(m.Ksetra??m.ksetra??""),role,photo:photo||APP_LOGO};setCurrentUser(user);try{localStorage.setItem(SESSION_KEY,JSON.stringify(user))}catch{};setView("home");return null}catch(e){console.error("Login error:",e);return `Database error: ${e?.message||"Unknown error"}`} };
  const createProject=async d=>{try{const created=await sb("projects",{method:"POST",headers:{Prefer:"return=representation"},body:JSON.stringify([{name:d.name,category:d.category,description:d.description,event_id:d.eventId||null,project_date:d.projectStartDate,project_start_date:d.projectStartDate,project_end_date:d.projectEndDate,project_dates:d.projectDates,enable_photos:d.enablePhotos,enable_videos:d.enableVideos,enable_attendance:d.enableAttendance,enable_forms:d.enableForms,cover_photo:d.coverPhoto||null,assigned_members:d.assignedMembers,assigned_karyakarta:d.assignedKaryakarta,created_by:currentUser.id}])});const projectId=created?.[0]?.id;if(!projectId)throw new Error("Project was created without an ID.");if(d.coverPhoto&&d.coverFile){let cover=d.coverPhoto;try{const compressed=await compressImage(d.coverFile,1400,.80);try{const blob=await (await fetch(compressed)).blob();cover=await uploadToBucket(blob,`projects/${encodeURIComponent(String(projectId))}/${uid("cover")}.jpg`)}catch{cover=compressed}}catch{}await sb(`projects?id=eq.${encodeURIComponent(projectId)}`,{method:"PATCH",body:JSON.stringify({cover_photo:cover})})}await loadProjects();appToast("Project created.","success")}catch(e){console.error("Create project error",e);appToast(`Could not create project. ${e?.message||e}`,"error");throw e}};
  const createEvent=async d=>{await sb("events",{method:"POST",body:JSON.stringify([{name:d.name,description:d.description,start_date:d.startDate,end_date:d.endDate,created_by:currentUser.id}])});await loadEvents();appToast("Event created.","success")};
  const updateEvent=async(ev,d)=>{await sb(`events?id=eq.${encodeURIComponent(ev.id)}`,{method:"PATCH",body:JSON.stringify({name:d.name,description:d.description,start_date:d.startDate,end_date:d.endDate})});await loadEvents();appToast("Event updated.","success")};
  const deleteEvent=async ev=>{if(!window.confirm(`Delete event “${ev.name}”? Projects inside it will remain, but will no longer belong to this event.`))return;await sb(`events?id=eq.${encodeURIComponent(ev.id)}`,{method:"DELETE"});await loadEvents();await loadProjects();appToast("Event deleted.","success")};
  if(loading)return <div style={{minHeight:"100vh",display:"grid",placeItems:"center",background:"#f9fafb"}}><Loader2 className="animate-spin" color={C.brand}/></div>;
  if(error)return <div style={{minHeight:"100vh",display:"grid",placeItems:"center",padding:20,background:"#f9fafb",...sans}}><div style={{maxWidth:500,background:"white",border:"1px solid #e5e7eb",borderRadius:6,padding:18}}><div style={{fontSize:14,fontWeight:700}}>Supabase connection error</div><div style={{fontSize:12,color:"#6b7280",marginTop:7,lineHeight:1.5}}>{error}</div></div></div>;
  if(!currentUser)return <LoginScreen onLogin={login}/>;
  const activeProject=projects.find(p=>p.id===activeProjectId);
  return <div className="baps-app-shell" style={{minHeight:"100vh",background:"#f9fafb",...sans}}><ToastHost/><div style={{position:"fixed",top:"calc(env(safe-area-inset-top,0px) + 10px)",right:14,zIndex:60,pointerEvents:"none",display:"flex",alignItems:"center",gap:8}}><div style={{pointerEvents:"auto",display:"flex",alignItems:"center",gap:8}}>{view==="projects"&&currentUser.role==="admin"&&<button type="button" aria-label="New project" title="New project" onClick={()=>document.querySelector('[data-new-project-trigger]')?.click()} style={{width:38,height:38,borderRadius:12,border:"1px solid #dbe3ec",background:"white",color:C.brand,display:"grid",placeItems:"center",cursor:"pointer",boxShadow:SHADOW.flat}}><Plus size={18}/></button>}{view!=="notifications"&&<NotificationBell currentUser={currentUser} projects={projects} onOpen={()=>setView("notifications")}/>}</div></div><div className="baps-app-frame" style={{maxWidth:1000,minHeight:"100vh",margin:"0 auto",background:"#f9fafb",display:"flex",flexDirection:"column",paddingBottom:"calc(82px + env(safe-area-inset-bottom,0px))"}}><div style={{flex:1}}>{view==="home"&&<HomeScreen currentUser={currentUser} projects={projects} setView={setView}/>} {view==="events"&&<EventsScreen events={events.filter(ev=>currentUser.role==="admin"||projects.some(p=>p.eventId===ev.id&&(((p.assignedMembers||[]).some(id=>samePersonId(id,currentUser.id)))||((p.assignedKaryakarta||[]).some(id=>samePersonId(id,currentUser.id))))))} projects={projects.filter(p=>currentUser.role==="admin"||((p.assignedMembers||[]).some(id=>samePersonId(id,currentUser.id)))||((p.assignedKaryakarta||[]).some(id=>samePersonId(id,currentUser.id))))} isAdmin={currentUser.role==="admin"} setView={setView} onCreate={createEvent} onUpdate={updateEvent} onDelete={deleteEvent} onEdit={p=>{setProjectEdit(p);setView("projects")}} members={members} onCreateProject={createProject}/>} {view==="projects"&&<ProjectsScreen events={events} projects={currentUser.role==="admin"?projects:currentUser.role==="karyakarta"?projects.filter(p=>(p.assignedKaryakarta||[]).some(id=>samePersonId(id,currentUser.id))):projects.filter(p=>(p.assignedMembers||[]).some(id=>samePersonId(id,currentUser.id)))} members={members} isAdmin={currentUser.role==="admin"} setView={setView} onCreate={createProject} onEdit={p=>{setProjectEdit(p);setView("projects")}}/>} {projectEdit&&view==="projects"&&currentUser.role==="admin"&&<Modal open={!!projectEdit} title="Edit project" description="Update project details, haribhakto and project karyakartas." onClose={()=>setProjectEdit(null)} wide><ProjectForm initial={projectEdit} members={members} events={events} onCancel={()=>setProjectEdit(null)} onSave={async d=>{try{await sb(`projects?id=eq.${encodeURIComponent(projectEdit.id)}`,{method:"PATCH",body:JSON.stringify({name:d.name,category:d.category,description:d.description,event_id:d.eventId||null,project_date:d.projectStartDate,project_start_date:d.projectStartDate,project_end_date:d.projectEndDate,project_dates:d.projectDates,enable_photos:d.enablePhotos,enable_videos:d.enableVideos,enable_attendance:d.enableAttendance,enable_forms:d.enableForms,cover_photo:d.coverPhoto||null,assigned_members:d.assignedMembers,assigned_karyakarta:d.assignedKaryakarta})});if(d.coverPhoto&&d.coverFile){let cover=d.coverPhoto;try{const compressed=await compressImage(d.coverFile,1400,.80);try{const blob=await (await fetch(compressed)).blob();cover=await uploadToBucket(blob,`projects/${encodeURIComponent(String(projectEdit.id))}/${uid("cover")}.jpg`)}catch{cover=compressed}}catch{}await sb(`projects?id=eq.${encodeURIComponent(projectEdit.id)}`,{method:"PATCH",body:JSON.stringify({cover_photo:cover})})}setProjectEdit(null);await loadProjects();appToast("Project updated.","success")}catch(e){appToast(`Could not update project. ${e?.message||"Unknown database error"}`,"error");throw e}}}/></Modal>} {view==="projectDetail"&&activeProject&&<ProjectDetail project={activeProject} currentUser={currentUser} members={members} events={events} setView={setView} refreshProjects={loadProjects}/>} {view==="notifications"&&<NotificationBell currentUser={currentUser} projects={projects} fullPage onClose={()=>setView("home")} />} {view==="profile"&&<ProfileScreen currentUser={currentUser} onLogout={()=>{setCurrentUser(null);try{localStorage.removeItem(SESSION_KEY)}catch{}setView("home")}}/>} {view==="admin"&&currentUser.role==="admin"&&<AdminScreen members={members} projects={projects} events={events} refreshMembers={loadMembers} refreshProjects={loadProjects} refreshEvents={loadEvents} onCreateProject={createProject} currentUser={currentUser}/>}</div><BottomNav view={view} setView={setView} isAdmin={currentUser.role==="admin"}/></div></div>;
}
